package ui

import "encoding/json"

// ToolCallEvent 描述一次工具调用事件。
// UI 只关心展示，因此这里保留最小字段集合。
type ToolCallEvent struct {
	ID         string
	Name       string
	Input      json.RawMessage
	OldContent string // 文件变更工具执行前的旧文件内容（Write/Edit），由调用方在工具执行前同步读取
}

// ToolResultEvent 描述一次工具执行结果事件。
// Name 单独保留一份，避免 UI 还要再从其他结构推断工具名。
type ToolResultEvent struct {
	ToolUseID string
	Name      string
	Content   string
	IsError   bool
}

// SystemEvent 描述由后台任务或控制器产生的系统消息。
type SystemEvent struct {
	Title string
	Body  string
	Color string // 可选：标题颜色（lipgloss 颜色字符串），与 subagents 面板保持一致
}

// UI 定义 loop 层依赖的最小输出接口。
// 当前既要支持纯文本流式渲染，也要支持工具调用/结果事件展示。
type UI interface {
	OnAssistantDelta(text string) error
	OnToolCall(event ToolCallEvent) error
	OnToolResult(event ToolResultEvent) error
	OnDone() error
}

// ThinkingDeltaReceiver 是 UI 的可选扩展，用于接收模型 thinking 流。
type ThinkingDeltaReceiver interface {
	OnThinkingDelta(text string) error
}

// SystemNotifier 是 UI 的可选扩展，用于接收后台任务完成等系统事件。
type SystemNotifier interface {
	OnSystemMessage(event SystemEvent) error
}

// OldContentConsumer 是 UI 的可选扩展，声明该 UI 会消费 ToolCallEvent.OldContent。
// 未实现此接口的 UI（如 sinkUI）不会触发磁盘读取，避免浪费 I/O。
type OldContentConsumer interface {
	ConsumesOldContent() bool
}

package loop

import (
	"codex-agent-go/internal/message"
	"codex-agent-go/internal/model"
	"codex-agent-go/internal/skill"
	"codex-agent-go/internal/tokentracer"
	"codex-agent-go/internal/tool"
	"codex-agent-go/internal/ui"
	"context"
	"encoding/json"
	"fmt"
	"html"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
)

const (
	maxToolRounds       = 500
	toolUseResponseType = "tool_use"
)

// ModelStreamer 是 loop 层依赖的最小模型流式接口。
type ModelStreamer interface {
	StreamMessage(ctx context.Context, messages []message.Message, tools []model.ToolDefinition) (<-chan model.StreamEvent, error)
}

// HistoryStore 是 Runner 依赖的最小历史存储接口。
// loop 层只关心“加载历史”和“追加历史”，不需要知道完整 session 能力。
type HistoryStore interface {
	LoadResolvedHistory(ctx context.Context, sessionID string) ([]message.Message, error)
	Append(ctx context.Context, sessionID string, msgs ...message.Message) error
}

type historyExistenceStore interface {
	Exists(ctx context.Context, sessionID string) (bool, error)
}

// Runner 负责单轮工具闭环调度。
// SubagentTokensProvider returns the cumulative token usage for all subagents
// spawned by a given parent session.
type SubagentTokensProvider interface {
	TotalSubagentTokens(parentSessionID string) int
}

type modelUsageReceiver interface {
	OnModelUsage(usage model.Usage)
}

type Runner struct {
	mu        sync.RWMutex
	model     ModelStreamer
	ui        ui.UI
	registry  *tool.Registry
	store     HistoryStore
	sessionID string
	workRoot  string // 工具使用的 workspace 根目录，用于解析相对文件路径
	prompt    *PromptBuilder
	// history 保存”已经成功完成”的多轮对话消息。
	// 当前调用路径是串行的，因此这里先不引入锁。
	// TODO: 如果后续要把 Runner 暴露给并发调用方，需要为 history 增加互斥保护。
	history                []message.Message
	usage                  model.Usage
	usageKnown             bool
	sessionUsage           model.Usage
	sessionUsageKnown      bool
	supplements            []string
	systemSupplement       string
	compactToolPrompt      bool
	streamMAEnabled        bool
	streamMASubagents      StreamMASubagentRunner
	subagentTokensProvider SubagentTokensProvider
	skillRegistry          *skill.Registry
	activeSkillContext     string
	tokenTracer            *tokentracer.Tracer
	traceStageID           string
	traceAgentID           string
}

type tokenUsageTotals struct {
	used   int
	cache  int
	output int
}

type ContextStats struct {
	UsedTokens  int
	CacheTokens int
	LimitTokens int
}

type outputMode int

const (
	outputModeUndecided outputMode = iota
	outputModeVisible
	outputModeSuppressed
)

type turnState struct {
	content      strings.Builder
	pending      strings.Builder
	toolCalls    []message.ToolCall
	wroteOutput  bool
	outputMode   outputMode
	usage        model.Usage
	usageKnown   bool
	traceStageID string
	traceAgentID string
}

type toolUseEnvelope struct {
	Type  string          `json:"type"`
	ID    string          `json:"id"`
	Name  string          `json:"name"`
	Input json.RawMessage `json:"input"`
}

// NewRunner 创建调度器。
func NewRunner(model ModelStreamer, output ui.UI, registry *tool.Registry, store HistoryStore, sessionID string) *Runner {
	return NewRunnerWithInstructionRoot(model, output, registry, store, sessionID, "")
}

// NewRunnerWithInstructionRoot 创建带项目指令根目录的调度器。
func NewRunnerWithInstructionRoot(model ModelStreamer, output ui.UI, registry *tool.Registry, store HistoryStore, sessionID, instructionRoot string) *Runner {
	return &Runner{
		model:           model,
		ui:              output,
		registry:        registry,
		store:           store,
		sessionID:       sessionID,
		workRoot:        instructionRoot,
		prompt:          NewPromptBuilder(NewInstructionManager(instructionRoot)),
		skillRegistry:   skill.NewRegistry(skill.DefaultRoots(instructionRoot)),
		streamMAEnabled: true,
	}
}

// RunTurn 执行一次最小工具闭环流程，并返回最终 assistant 消息。
func (runner *Runner) RunTurn(ctx context.Context, input string) (msg message.Message, err error) {
	if err := runner.validate(); err != nil {
		return message.Message{}, err
	}
	runner.activateSkillContext(input)
	defer runner.clearActiveSkillContext()

	if runner.historyIsNil() && runner.store != nil {
		messages, err := runner.store.LoadResolvedHistory(ctx, runner.sessionID)
		if err != nil {
			if existsStore, ok := runner.store.(historyExistenceStore); ok {
				exists, existsErr := existsStore.Exists(ctx, runner.sessionID)
				if existsErr != nil {
					return message.Message{}, existsErr
				}
				if !exists {
					runner.setHistoryIfNil(nil)
				} else {
					return message.Message{}, err
				}
			} else {
				return message.Message{}, err
			}
		} else {
			runner.setHistoryIfNil(messages)
		}
	}

	if invocation, ok := parseStreamMAInvocation(input); ok {
		if !runner.currentStreamMAEnabled() {
			return message.Message{}, fmt.Errorf("streamma is disabled; start with -streamma=true or set GOCODE_STREAMMA=1 to enable /streamma")
		}
		return runner.runStreamMATurn(ctx, input, invocation)
	}

	trace := runner.beginTraceTurn(input, "conversation")
	defer func() {
		runner.finishTraceTurn(trace, err)
	}()

	// 每一轮都基于“已提交的历史副本”工作。
	// 这样即使当前轮中途失败，也不会污染下一轮上下文。
	history, injectedSupplements := runner.buildTurnHistory(input)
	committed := false
	defer func() {
		if !committed && len(injectedSupplements) > 0 {
			runner.prependSupplements(injectedSupplements)
		}
	}()
	for round := 0; round < maxToolRounds; round++ {
		var injected []string
		history, injected = runner.appendPendingSupplements(history)
		injectedSupplements = append(injectedSupplements, injected...)

		assistantMessage, err := runner.runModelTurn(ctx, history)
		if err != nil {
			return message.Message{}, err
		}
		history = append(history, assistantMessage)

		toolCalls := toolCallsFromMessage(assistantMessage)
		if len(toolCalls) == 0 {
			// 只有当本轮完整结束时，才把本轮消息提交为新的会话历史。
			if err := runner.commitHistory(ctx, history); err != nil {
				return message.Message{}, err
			}
			committed = true
			return assistantMessage, nil
		}

		toolResult, err := runner.runToolCalls(ctx, toolCalls)
		if err != nil {
			return message.Message{}, err
		}
		history = append(history, toolResult)
	}

	return message.Message{}, fmt.Errorf("tool loop exceeded max rounds: %d", maxToolRounds)
}

func (runner *Runner) validate() error {
	if runner == nil || runner.model == nil || runner.ui == nil {
		return fmt.Errorf("runner 未初始化: model 或 ui 为空")
	}
	return nil
}

// SetSkillRegistry overrides the local skill registry. It is primarily useful
// for tests and embedded callers that want a constrained skill search path.
func (runner *Runner) SetSkillRegistry(registry *skill.Registry) {
	if runner == nil {
		return
	}
	runner.mu.Lock()
	defer runner.mu.Unlock()
	runner.skillRegistry = registry
}

// SkillRoots returns the active skill search roots for tools that need to read
// selected skill references without opening write access outside the workspace.
func (runner *Runner) SkillRoots() []string {
	registry := runner.currentSkillRegistry()
	if registry == nil {
		return nil
	}
	return registry.Roots()
}

func (runner *Runner) activateSkillContext(input string) {
	if runner == nil {
		return
	}
	registry := runner.currentSkillRegistry()
	if registry == nil {
		runner.clearActiveSkillContext()
		return
	}
	contextText, _, errs := registry.InstructionContext(input)
	runner.mu.Lock()
	runner.activeSkillContext = contextText
	runner.mu.Unlock()
	for _, err := range errs {
		if err != nil {
			runner.notifySystem("skills", err.Error())
		}
	}
}

func (runner *Runner) clearActiveSkillContext() {
	if runner == nil {
		return
	}
	runner.mu.Lock()
	defer runner.mu.Unlock()
	runner.activeSkillContext = ""
}

func (runner *Runner) currentSkillRegistry() *skill.Registry {
	if runner == nil {
		return nil
	}
	runner.mu.RLock()
	defer runner.mu.RUnlock()
	return runner.skillRegistry
}

func (runner *Runner) currentSkillContext() string {
	if runner == nil {
		return ""
	}
	runner.mu.RLock()
	defer runner.mu.RUnlock()
	return runner.activeSkillContext
}

func (runner *Runner) runModelTurn(ctx context.Context, history []message.Message) (message.Message, error) {
	var tools []model.ToolDefinition
	if runner.registry != nil {
		tools = runner.registry.Definitions()
	}
	events, err := runner.model.StreamMessage(ctx, runner.buildModelMessages(history), tools)
	if err != nil {
		return message.Message{}, err
	}

	return runner.consumeStream(ctx, events)
}

func buildUserMessages(input string) []message.Message {
	return []message.Message{
		{
			Role:    message.RoleUser,
			Content: input,
		},
	}
}

// SubmitSupplement records a user supplement that should be injected into the
// next available model step. It is safe to call while RunTurn is streaming.
func (runner *Runner) SubmitSupplement(input string) bool {
	input = strings.TrimSpace(input)
	if runner == nil || input == "" {
		return false
	}
	runner.mu.Lock()
	runner.supplements = append(runner.supplements, input)
	runner.mu.Unlock()
	return true
}

// PendingSupplementCount returns supplements that have not yet been injected.
func (runner *Runner) PendingSupplementCount() int {
	if runner == nil {
		return 0
	}
	runner.mu.RLock()
	defer runner.mu.RUnlock()
	return len(runner.supplements)
}

// buildTurnHistory 复制已完成历史，并在尾部追加当前用户输入。
// 这样单轮执行可以安全地在本地 history 上反复追加 tool_use / tool_result。
func (runner *Runner) buildTurnHistory(input string) ([]message.Message, []string) {
	runner.mu.RLock()
	history := append([]message.Message(nil), runner.history...)
	runner.mu.RUnlock()
	supplements := runner.drainSupplements()
	history = append(history, buildSupplementMessages(supplements)...)
	history = append(history, buildUserMessages(input)...)
	return history, supplements
}

func (runner *Runner) appendPendingSupplements(history []message.Message) ([]message.Message, []string) {
	supplements := runner.drainSupplements()
	if len(supplements) == 0 {
		return history, nil
	}
	return append(history, buildSupplementMessages(supplements)...), supplements
}

func (runner *Runner) drainSupplements() []string {
	if runner == nil {
		return nil
	}
	runner.mu.Lock()
	defer runner.mu.Unlock()
	if len(runner.supplements) == 0 {
		return nil
	}
	supplements := append([]string(nil), runner.supplements...)
	runner.supplements = nil
	return supplements
}

func (runner *Runner) prependSupplements(supplements []string) {
	if runner == nil || len(supplements) == 0 {
		return
	}
	runner.mu.Lock()
	defer runner.mu.Unlock()
	combined := make([]string, 0, len(supplements)+len(runner.supplements))
	combined = append(combined, supplements...)
	combined = append(combined, runner.supplements...)
	runner.supplements = combined
}

func buildSupplementMessages(supplements []string) []message.Message {
	messages := make([]message.Message, 0, len(supplements))
	for _, supplement := range supplements {
		supplement = strings.TrimSpace(supplement)
		if supplement == "" {
			continue
		}
		messages = append(messages, message.Message{
			Role:    message.RoleUser,
			Content: "Supplemental instruction submitted while this turn was running:\n" + supplement,
		})
	}
	return messages
}

// commitHistory 在一次 turn 成功结束后提交历史。
// 先计算新增消息，再更新内存、持久化磁盘，两步顺序不能颠倒。
func (runner *Runner) commitHistory(ctx context.Context, history []message.Message) error {
	if runner.store != nil {
		// 在更新 runner.history 之前，先用旧长度算出本轮新增的消息。
		// runner.history 是上一轮结束时的状态，history 是本轮完整状态。
		runner.mu.RLock()
		prevLen := len(runner.history)
		runner.mu.RUnlock()
		newMsgs := history[prevLen:]
		if len(newMsgs) > 0 {
			if err := runner.store.Append(ctx, runner.sessionID, newMsgs...); err != nil {
				return fmt.Errorf("保存会话历史失败: %w", err)
			}
		}
	}

	// 持久化成功后再更新内存副本。
	runner.mu.Lock()
	runner.history = append([]message.Message(nil), history...)
	runner.mu.Unlock()
	return nil
}

// ResetHistory 清空当前对话上下文。
// 交互式 REPL 可以用它实现 /clear 这类命令。
// TODO: 接入会话持久化后，这里还需要同步清理对应的 session 数据。
func (runner *Runner) ResetHistory() {
	runner.mu.Lock()
	defer runner.mu.Unlock()
	runner.history = []message.Message{}
	runner.usage = model.Usage{}
	runner.usageKnown = false
	runner.sessionUsage = model.Usage{}
	runner.sessionUsageKnown = false
	runner.supplements = nil
}

// LoadHistory 从 store 加载指定 session 的历史，并替换当前 runner 的历史。
// 同时更新 runner.sessionID 以指向新会话，并返回加载到的消息供 UI 重建 transcript。
func (runner *Runner) LoadHistory(ctx context.Context, sessionID string) ([]message.Message, error) {
	if runner.store == nil {
		return nil, fmt.Errorf("runner store is nil")
	}
	messages, err := runner.store.LoadResolvedHistory(ctx, sessionID)
	if err != nil {
		return nil, err
	}
	runner.mu.Lock()
	runner.history = append([]message.Message(nil), messages...)
	runner.sessionID = sessionID
	runner.usage = model.Usage{}
	runner.usageKnown = false
	runner.sessionUsage = model.Usage{}
	runner.sessionUsageKnown = false
	runner.supplements = nil
	runner.mu.Unlock()
	return messages, nil
}

func (runner *Runner) ContextStats(limitTokens int, _ string) ContextStats {
	if limitTokens <= 0 {
		limitTokens = 1024 * 1024
	}
	if runner == nil {
		return ContextStats{LimitTokens: limitTokens}
	}

	runner.mu.RLock()
	usage := runner.usage
	usageKnown := runner.usageKnown
	sessionID := runner.sessionID
	provider := runner.subagentTokensProvider
	runner.mu.RUnlock()

	current := usageTotalsFromUsage(usage, usageKnown)
	subagentTokens := 0
	if provider != nil {
		subagentTokens = provider.TotalSubagentTokens(sessionID)
	}
	return ContextStats{
		UsedTokens:  current.used + subagentTokens,
		CacheTokens: current.cache,
		LimitTokens: limitTokens,
	}
}

func (runner *Runner) historyIsNil() bool {
	runner.mu.RLock()
	defer runner.mu.RUnlock()
	return runner.history == nil
}

func (runner *Runner) setHistoryIfNil(history []message.Message) {
	runner.mu.Lock()
	defer runner.mu.Unlock()
	if runner.history == nil {
		runner.history = append([]message.Message(nil), history...)
	}
}

func buildSystemMessage(content string) message.Message {
	return message.Message{
		Role:    message.RoleSystem,
		Content: content,
	}
}

func buildAssistantMessage(content string) message.Message {
	return message.Message{
		Role:    message.RoleAssistant,
		Content: content,
	}
}

func buildToolResultMessage(toolUseID, content string, isError bool) message.Message {
	return message.Message{
		Role: message.RoleUser,
		ToolResult: &message.ToolResult{
			ToolUseID: toolUseID,
			Content:   content,
			IsError:   isError,
		},
	}
}

func buildToolResultsMessage(results []message.ToolResult) message.Message {
	msg := message.Message{Role: message.RoleUser}
	if len(results) == 0 {
		return msg
	}
	if len(results) == 1 {
		result := results[0]
		msg.ToolResult = &result
		return msg
	}
	msg.ToolResults = append([]message.ToolResult(nil), results...)
	return msg
}

func toolCallsFromMessage(msg message.Message) []message.ToolCall {
	if len(msg.ToolUses) > 0 {
		return append([]message.ToolCall(nil), msg.ToolUses...)
	}
	if msg.ToolUse == nil {
		return nil
	}
	return []message.ToolCall{*msg.ToolUse}
}

func toolResultsFromMessage(msg message.Message) []message.ToolResult {
	if len(msg.ToolResults) > 0 {
		return append([]message.ToolResult(nil), msg.ToolResults...)
	}
	if msg.ToolResult == nil {
		return nil
	}
	return []message.ToolResult{*msg.ToolResult}
}

func (runner *Runner) buildModelMessages(history []message.Message) []message.Message {
	messages := make([]message.Message, 0, len(history)+1)
	messages = append(messages, buildSystemMessage(runner.buildSystemPrompt()))
	for _, msg := range history {
		rendered := renderMessageForModel(msg)
		// 跳过空 content 的 assistant 消息，避免发送 {"role":"assistant"} 触发 API 400 错误。
		// 空 assistant 消息可能来自模型返回空流式内容的边界情况。
		if rendered.Role == message.RoleAssistant && rendered.Content == "" {
			continue
		}
		messages = append(messages, rendered)
	}
	return messages
}

// 构建系统提示词
func (runner *Runner) buildSystemPrompt() string {
	descriptions := []string{}
	if runner.registry != nil {
		runner.mu.RLock()
		compactToolPrompt := runner.compactToolPrompt
		runner.mu.RUnlock()
		if compactToolPrompt {
			descriptions = runner.registry.DescribeBrief()
		} else {
			descriptions = runner.registry.Describe()
		}
	}
	if runner.prompt == nil {
		runner.prompt = NewPromptBuilder(NewInstructionManager(""))
	}
	prompt := runner.prompt.Build(descriptions)
	runner.mu.RLock()
	supplement := runner.systemSupplement
	skillContext := runner.activeSkillContext
	runner.mu.RUnlock()
	var sections []string
	if strings.TrimSpace(skillContext) != "" {
		sections = append(sections, "Selected skill instructions:\n"+strings.TrimSpace(skillContext))
	}
	if strings.TrimSpace(supplement) != "" {
		sections = append(sections, "Additional system instructions:\n"+strings.TrimSpace(supplement))
	}
	if len(sections) == 0 {
		return prompt
	}
	return strings.TrimRight(prompt, "\n") + "\n\n" + strings.Join(sections, "\n\n") + "\n"
}

func renderMessageForModel(msg message.Message) message.Message {
	switch {
	case len(toolCallsFromMessage(msg)) > 0:
		calls := toolCallsFromMessage(msg)
		parts := make([]string, 0, len(calls))
		for _, call := range calls {
			parts = append(parts, marshalJSON(toolUseEnvelope{Type: toolUseResponseType, ID: call.ID, Name: call.Name, Input: call.Input}))
		}
		return message.Message{
			Role:    message.RoleAssistant,
			Content: strings.Join(parts, "\n"),
		}
	case len(toolResultsFromMessage(msg)) > 0:
		results := toolResultsFromMessage(msg)
		parts := make([]string, 0, len(results))
		for _, result := range results {
			parts = append(parts, marshalJSON(result))
		}
		label := "TOOL_RESULT:\n"
		if len(results) > 1 {
			label = "TOOL_RESULTS:\n"
		}
		return message.Message{
			Role:    message.RoleUser,
			Content: label + strings.Join(parts, "\n"),
		}
	default:
		return message.Message{
			Role:    msg.Role,
			Content: msg.Content,
		}
	}
}

func marshalJSON(v any) string {
	data, err := json.Marshal(v)
	if err != nil {
		return ""
	}
	return string(data)
}

func (runner *Runner) consumeStream(ctx context.Context, events <-chan model.StreamEvent) (message.Message, error) {
	var state turnState
	state.traceStageID, state.traceAgentID = runner.currentTraceIDs()

	for ev := range events {
		msg, done, err := runner.handleEvent(&state, ev)
		if err != nil {
			return message.Message{}, err
		}
		if done {
			return msg, nil
		}
	}

	return runner.finishWithoutDone(ctx, state)
}

func (runner *Runner) handleEvent(state *turnState, ev model.StreamEvent) (message.Message, bool, error) {
	if ev.Err != nil {
		return message.Message{}, false, runner.failAfterPartialOutput(state.wroteOutput, ev.Err)
	}
	if ev.Usage != nil {
		runner.recordUsageEvent(state, *ev.Usage)
	}
	if err := runner.appendThinking(ev.Thinking); err != nil {
		return message.Message{}, false, err
	}

	if err := runner.appendDelta(state, ev.Delta); err != nil {
		return message.Message{}, false, err
	}
	appendStreamToolCalls(state, ev.ToolCalls)

	if !ev.Done {
		return message.Message{}, false, nil
	}

	msg, err := runner.finalizeAssistantMessage(state)
	return msg, true, err
}

func (runner *Runner) recordUsageEvent(state *turnState, usage model.Usage) {
	previousTrace := tokentracer.UsageFromModelUsage(state.usage)
	previous := usageTotalsFromUsage(state.usage, state.usageKnown)
	state.usage = mergeUsageSnapshot(state.usage, usage)
	state.usageKnown = true
	current := usageTotalsFromUsage(state.usage, true)
	runner.setCurrentUsage(state.usage)
	runner.addSessionUsage(current.delta(previous))
	runner.emitModelUsage(state.usage)
	currentTrace := tokentracer.UsageFromModelUsage(state.usage)
	runner.recordTraceUsage(state.traceStageID, state.traceAgentID, currentTrace.Delta(previousTrace), map[string]any{
		"source": "model_stream",
	})
}

func (runner *Runner) emitModelUsage(usage model.Usage) {
	if runner == nil || runner.ui == nil {
		return
	}
	receiver, ok := runner.ui.(modelUsageReceiver)
	if !ok {
		return
	}
	receiver.OnModelUsage(usage)
}

func (runner *Runner) setCurrentUsage(usage model.Usage) {
	runner.mu.Lock()
	defer runner.mu.Unlock()
	runner.usage = usage
	runner.usageKnown = true
}

func (runner *Runner) addSessionUsage(delta tokenUsageTotals) {
	runner.mu.Lock()
	defer runner.mu.Unlock()

	current := usageTotalsFromUsage(runner.sessionUsage, runner.sessionUsageKnown)
	current = current.add(delta)
	runner.sessionUsage = usageFromTotals(current)
	runner.sessionUsageKnown = true
}

func mergeUsageSnapshot(current, next model.Usage) model.Usage {
	if next.InputTokens != 0 {
		current.InputTokens = next.InputTokens
	}
	if next.OutputTokens != 0 {
		current.OutputTokens = next.OutputTokens
	}
	if next.CacheCreationInputTokens != 0 {
		current.CacheCreationInputTokens = next.CacheCreationInputTokens
	}
	if next.CacheReadInputTokens != 0 {
		current.CacheReadInputTokens = next.CacheReadInputTokens
	}
	if next.PromptTokens != 0 {
		current.PromptTokens = next.PromptTokens
	}
	if next.CompletionTokens != 0 {
		current.CompletionTokens = next.CompletionTokens
	}
	if next.TotalTokens != 0 {
		current.TotalTokens = next.TotalTokens
	}
	if next.PromptCacheHitTokens != 0 {
		current.PromptCacheHitTokens = next.PromptCacheHitTokens
	}
	if next.PromptCacheMissTokens != 0 {
		current.PromptCacheMissTokens = next.PromptCacheMissTokens
	}
	current.PromptTokensDetails = mergeTokenDetails(current.PromptTokensDetails, next.PromptTokensDetails)
	current.InputTokensDetails = mergeTokenDetails(current.InputTokensDetails, next.InputTokensDetails)
	return current
}

func mergeTokenDetails(current, next model.TokenDetails) model.TokenDetails {
	if next.CachedTokens != 0 {
		current.CachedTokens = next.CachedTokens
	}
	if next.CacheReadTokens != 0 {
		current.CacheReadTokens = next.CacheReadTokens
	}
	if next.CacheReadInputTokens != 0 {
		current.CacheReadInputTokens = next.CacheReadInputTokens
	}
	if next.CacheCreationTokens != 0 {
		current.CacheCreationTokens = next.CacheCreationTokens
	}
	if next.CacheCreationInputTokens != 0 {
		current.CacheCreationInputTokens = next.CacheCreationInputTokens
	}
	return current
}

func usageTotalsFromUsage(usage model.Usage, known bool) tokenUsageTotals {
	if !known {
		return tokenUsageTotals{}
	}
	used := usage.ContextTokenCount()
	cache := usage.CacheHitTokens()
	output := usage.CompletionTokenCount()
	if used < 0 {
		used = 0
	}
	if cache < 0 {
		cache = 0
	}
	if output < 0 {
		output = 0
	}
	if used < cache {
		used = cache
	}
	if cache > used {
		cache = used
	}
	if used < output {
		used = output
	}
	return tokenUsageTotals{used: used, cache: cache, output: output}
}

func usageFromTotals(t tokenUsageTotals) model.Usage {
	t = t.normalized()
	return model.Usage{
		PromptTokens:         maxInt(0, t.used-t.output),
		CompletionTokens:     t.output,
		TotalTokens:          t.used,
		PromptCacheHitTokens: t.cache,
	}
}

func (t tokenUsageTotals) add(other tokenUsageTotals) tokenUsageTotals {
	return tokenUsageTotals{
		used:   maxInt(0, t.used) + maxInt(0, other.used),
		cache:  maxInt(0, t.cache) + maxInt(0, other.cache),
		output: maxInt(0, t.output) + maxInt(0, other.output),
	}.normalized()
}

func (t tokenUsageTotals) delta(previous tokenUsageTotals) tokenUsageTotals {
	return tokenUsageTotals{
		used:   maxInt(0, t.used-previous.used),
		cache:  maxInt(0, t.cache-previous.cache),
		output: maxInt(0, t.output-previous.output),
	}
}

func (t tokenUsageTotals) normalized() tokenUsageTotals {
	if t.used < 0 {
		t.used = 0
	}
	if t.cache < 0 {
		t.cache = 0
	}
	if t.output < 0 {
		t.output = 0
	}
	if t.used < t.cache {
		t.used = t.cache
	}
	if t.cache > t.used {
		t.cache = t.used
	}
	if t.used < t.output {
		t.used = t.output
	}
	return t
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func (runner *Runner) appendDelta(state *turnState, delta string) error {
	if delta == "" {
		return nil
	}

	state.content.WriteString(delta)

	switch state.outputMode {
	case outputModeVisible:
		return runner.writeDelta(state, delta)
	case outputModeSuppressed:
		return nil
	}

	state.pending.WriteString(delta)
	state.outputMode = detectOutputMode(state.content.String())
	if state.outputMode == outputModeUndecided {
		return nil
	}
	if state.outputMode == outputModeSuppressed {
		state.pending.Reset()
		return nil
	}

	pending := state.pending.String()
	state.pending.Reset()
	return runner.writeDelta(state, pending)
}

func detectOutputMode(content string) outputMode {
	trimmed := strings.TrimSpace(content)
	if trimmed == "" {
		return outputModeUndecided
	}

	// 只要当前累计内容里已经能提取出合法 tool_use，就直接压制输出。
	if len(extractToolUseEnvelopes(trimmed)) > 0 {
		return outputModeSuppressed
	}

	// 对“看起来像工具前置说明”的内容持续保持观望，避免模型先输出大段
	// “我将使用工具……”，随后再跟 fenced tool_use JSON。
	if looksLikeToolPreamble(trimmed) {
		return outputModeUndecided
	}

	// 模型有时会把 tool_use JSON 包在 Markdown fence 里返回。
	// 这里一旦看到 “{” 或 “`” 开头，就先抑制输出，等 finalize 再判定
	// 它到底是工具调用还是普通文本，避免把 tool_use JSON 泄漏到终端。
	if strings.HasPrefix(trimmed, "{") || strings.HasPrefix(trimmed, "[") || strings.HasPrefix(trimmed, "`") {
		return outputModeSuppressed
	}

	// <tool_call>、<tool> 系列 以及 <简单标签名> 开头时直接抑制，等 finalize 确认
	lowerTrimmed := strings.ToLower(trimmed)
	if strings.HasPrefix(lowerTrimmed, "<tool_call") ||
		strings.HasPrefix(lowerTrimmed, "<tool ") ||
		strings.HasPrefix(lowerTrimmed, "<tool>") {
		return outputModeSuppressed
	}
	// <glob>、<bash>、<read> 等简单标签名开头（<toolname>JSON 格式）
	if strings.HasPrefix(trimmed, "<") && !strings.HasPrefix(trimmed, "</") {
		end := strings.IndexByte(trimmed[1:], '>')
		if end != -1 && isSimpleXMLTagName(trimmed[1:end+1]) {
			return outputModeSuppressed
		}
	}

	return outputModeVisible
}

func looksLikeToolPreamble(trimmed string) bool {
	lower := strings.ToLower(trimmed)
	hints := []string{
		"我将",
		"我会",
		"我来",
		"好的，我来",
		"让我",
		"先使用",
		"首先使用",
		"读取",
		"读出",
		"遍历",
		"列出",
		"查看",
		"i will",
		"i'll",
		"let me",
		"tool_use",
		"<invoke",
		"<tool_call",
		"<tool ",
		"<tool>",
		"工具",
		"调用",
		"使用",
		"ls",
		"read",
		"write",
		"grep",
		"glob",
		"bash",
		"webfetch",
		"```",
	}
	for _, hint := range hints {
		if strings.Contains(lower, strings.ToLower(hint)) {
			return true
		}
	}
	return false
}

func (runner *Runner) appendThinking(thinking string) error {
	if thinking == "" {
		return nil
	}
	runner.recordTraceEvent("thinking_delta", map[string]any{
		"text":  thinking,
		"bytes": len([]byte(thinking)),
	})
	if sink, ok := runner.ui.(ui.ThinkingDeltaReceiver); ok {
		if err := sink.OnThinkingDelta(thinking); err != nil {
			return err
		}
	}
	return nil
}

func (runner *Runner) writeDelta(state *turnState, delta string) error {
	if delta == "" {
		return nil
	}
	runner.recordTraceEvent("assistant_delta", map[string]any{
		"text":  delta,
		"bytes": len([]byte(delta)),
	})

	if err := runner.ui.OnAssistantDelta(delta); err != nil {
		return runner.failAfterPartialOutput(state.wroteOutput, err)
	}
	state.wroteOutput = true
	return nil
}

func (runner *Runner) finalizeAssistantMessage(state *turnState) (message.Message, error) {
	if len(state.toolCalls) > 0 {
		return buildAssistantToolCallMessage(state.toolCalls), nil
	}

	msg := parseAssistantMessage(state.content.String())
	if len(toolCallsFromMessage(msg)) > 0 {
		return msg, nil
	}

	if !state.wroteOutput {
		if err := runner.writeDelta(state, msg.Content); err != nil {
			return message.Message{}, err
		}
	}
	if err := runner.ui.OnDone(); err != nil {
		return message.Message{}, err
	}

	return msg, nil
}

func parseAssistantMessage(content string) message.Message {
	trimmed := strings.TrimSpace(content)
	if trimmed == "" {
		return buildAssistantMessage("")
	}

	envelopes := extractToolUseEnvelopes(trimmed)
	if len(envelopes) == 0 {
		return buildAssistantMessage(content)
	}

	calls := make([]message.ToolCall, 0, len(envelopes))
	for _, envelope := range envelopes {
		calls = append(calls, message.ToolCall{
			ID:    envelope.ID,
			Name:  envelope.Name,
			Input: envelope.Input,
		})
	}

	return buildAssistantToolCallMessage(calls)
}

func appendStreamToolCalls(state *turnState, calls []message.ToolCall) {
	if state == nil || len(calls) == 0 {
		return
	}
	state.toolCalls = append(state.toolCalls, calls...)
	state.pending.Reset()
	state.outputMode = outputModeSuppressed
}

func buildAssistantToolCallMessage(calls []message.ToolCall) message.Message {
	calls = normalizeToolCalls(calls)
	msg := message.Message{Role: message.RoleAssistant}
	if len(calls) == 1 {
		call := calls[0]
		msg.ToolUse = &call
	} else if len(calls) > 1 {
		msg.ToolUses = calls
		call := calls[0]
		msg.ToolUse = &call
	}
	return msg
}

func normalizeToolCalls(calls []message.ToolCall) []message.ToolCall {
	normalized := make([]message.ToolCall, 0, len(calls))
	for i, call := range calls {
		if strings.TrimSpace(call.Name) == "" {
			continue
		}
		if call.ID == "" {
			if len(calls) == 1 {
				call.ID = call.Name
			} else {
				call.ID = fmt.Sprintf("%s_%d", call.Name, i+1)
			}
		}
		if len(call.Input) == 0 {
			call.Input = json.RawMessage(`{}`)
		} else {
			call.Input = append(json.RawMessage(nil), call.Input...)
		}
		normalized = append(normalized, call)
	}
	return normalized
}

func extractToolUseEnvelope(trimmed string) (toolUseEnvelope, bool) {
	envelopes := extractToolUseEnvelopes(trimmed)
	if len(envelopes) == 0 {
		return toolUseEnvelope{}, false
	}
	return envelopes[0], true
}

// extractToolUseEnvelopes 从 assistant 输出中提取一个或多个合法的 tool_use 对象。
// 当前兼容七类格式：
// 1) 整段内容就是裸 JSON
// 2) 整段内容就是 fenced JSON
// 3) 说明文字中嵌入 fenced JSON 或裸 JSON
// 4) Claude/DeepSeek 兼容的 <invoke> + DSML 参数块
// 5) <tool_call><tool name="...">...</tool></tool_call> 格式
// 6) <tool><tool_call><name>X</name><input>JSON</input></tool_call></tool> 格式
// 7) <toolname>JSON</toolname> 格式（标签名即工具名）
func extractToolUseEnvelopes(trimmed string) []toolUseEnvelope {
	if envelopes, ok := decodeToolUseEnvelopes(trimmed); ok {
		return envelopes
	}

	if payload, ok := extractFencedToolUsePayload(trimmed); ok {
		if envelopes, matched := decodeToolUseEnvelopes(payload); matched {
			return envelopes
		}
	}

	if envelopes := extractEmbeddedToolUseEnvelopes(trimmed); len(envelopes) > 0 {
		return envelopes
	}

	if envelope, ok := extractInvokeToolUseEnvelope(trimmed); ok {
		return []toolUseEnvelope{envelope}
	}

	if envelope, ok := extractToolCallEnvelope(trimmed); ok {
		return []toolUseEnvelope{envelope}
	}

	if envelope, ok := extractTagNameToolEnvelope(trimmed); ok {
		return []toolUseEnvelope{envelope}
	}

	return nil
}

// extractTagNameToolEnvelope 处理 <toolname>JSON</toolname> 格式。
// 标签名即工具名，标签体为合法的 JSON 对象。
// 仅匹配标签名由字母/数字/下划线/连字符构成（无属性）的简单标签。
func extractTagNameToolEnvelope(content string) (toolUseEnvelope, bool) {
	for start := 0; start < len(content); {
		openIdx := strings.IndexByte(content[start:], '<')
		if openIdx == -1 {
			break
		}
		openIdx += start

		// 跳过结束标签
		if openIdx+1 < len(content) && content[openIdx+1] == '/' {
			start = openIdx + 2
			continue
		}

		// 找到标签结束 >
		closeAngle := strings.IndexByte(content[openIdx:], '>')
		if closeAngle == -1 {
			break
		}
		closeAngle += openIdx

		tagName := content[openIdx+1 : closeAngle]
		if !isSimpleXMLTagName(tagName) {
			start = closeAngle + 1
			continue
		}

		// 查找对应的结束标签
		closeTag := "</" + tagName + ">"
		closeIdx := strings.Index(strings.ToLower(content[closeAngle+1:]), strings.ToLower(closeTag))
		if closeIdx == -1 {
			start = closeAngle + 1
			continue
		}
		closeIdx += closeAngle + 1

		body := strings.TrimSpace(content[closeAngle+1 : closeIdx])
		// 标签体必须是有效的 JSON 对象
		if !strings.HasPrefix(body, "{") || !json.Valid([]byte(body)) {
			start = closeAngle + 1
			continue
		}

		return toolUseEnvelope{
			Type:  toolUseResponseType,
			Name:  tagName,
			Input: json.RawMessage(body),
		}, true
	}
	return toolUseEnvelope{}, false
}

// isSimpleXMLTagName 验证字符串是否为仅含字母/数字/下划线/连字符的简单标签名（无属性、无空格）。
func isSimpleXMLTagName(s string) bool {
	if s == "" {
		return false
	}
	for _, r := range s {
		if !((r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') ||
			(r >= '0' && r <= '9') || r == '_' || r == '-') {
			return false
		}
	}
	return true
}

// extractToolCallEnvelope 处理以下三类 XML 工具调用格式：
//
//	格式 A：<tool_call><tool name="X">body</tool></tool_call>
//	        （body 可以是 JSON 或 XML 参数，</tool> 可省略由 </tool_call> 关闭）
//
//	格式 B：<tool><tool_call><name>X</name><input>JSON</input></tool_call></tool>
//	        （DeepSeek 部分模型输出的格式）
//
//	格式 C：<tool_call><name>X</name><input>JSON</input></tool_call>
//	        （同格式 B 但无外层 <tool> 包装）
func extractToolCallEnvelope(content string) (toolUseEnvelope, bool) {
	lower := strings.ToLower(content)

	// 格式 B / C：通过 <name>...</name> + <input>...</input> 提取
	if envelope, ok := extractNameInputEnvelope(content, lower); ok {
		return envelope, true
	}

	// 格式 A：通过 <tool name="..."> 提取
	toolIdx := strings.Index(lower, "<tool ")
	if toolIdx == -1 {
		return toolUseEnvelope{}, false
	}

	tagEndRel := strings.IndexByte(content[toolIdx:], '>')
	if tagEndRel == -1 {
		return toolUseEnvelope{}, false
	}
	tagEnd := toolIdx + tagEndRel

	openTag := content[toolIdx : tagEnd+1]
	name := extractTagAttribute(openTag, "name")
	if name == "" {
		return toolUseEnvelope{}, false
	}

	bodyStart := tagEnd + 1
	bodyEnd := len(content)
	restLower := strings.ToLower(content[bodyStart:])
	if closeIdx := strings.Index(restLower, "</tool>"); closeIdx != -1 {
		bodyEnd = bodyStart + closeIdx
	} else if closeIdx := strings.Index(restLower, "</tool_call>"); closeIdx != -1 {
		bodyEnd = bodyStart + closeIdx
	}

	body := strings.TrimSpace(content[bodyStart:bodyEnd])
	input := decodeInvokeInput(body)

	return toolUseEnvelope{
		Type:  toolUseResponseType,
		Name:  name,
		Input: input,
	}, true
}

// extractNameInputEnvelope 提取 <name>X</name><input>JSON</input> 格式的工具调用。
func extractNameInputEnvelope(content, lower string) (toolUseEnvelope, bool) {
	nameStart := strings.Index(lower, "<name>")
	if nameStart == -1 {
		return toolUseEnvelope{}, false
	}
	nameEnd := strings.Index(lower[nameStart:], "</name>")
	if nameEnd == -1 {
		return toolUseEnvelope{}, false
	}
	nameEnd += nameStart
	name := strings.TrimSpace(content[nameStart+len("<name>") : nameEnd])
	if name == "" {
		return toolUseEnvelope{}, false
	}

	inputStart := strings.Index(lower, "<input>")
	if inputStart == -1 {
		return toolUseEnvelope{}, false
	}
	inputEnd := strings.Index(lower[inputStart:], "</input>")
	if inputEnd == -1 {
		return toolUseEnvelope{}, false
	}
	inputEnd += inputStart
	inputBody := strings.TrimSpace(content[inputStart+len("<input>") : inputEnd])

	input := decodeInvokeInput(inputBody)
	return toolUseEnvelope{
		Type:  toolUseResponseType,
		Name:  name,
		Input: input,
	}, true
}

func decodeToolUseEnvelope(payload string) (toolUseEnvelope, bool) {
	payload = strings.TrimSpace(payload)
	if !strings.HasPrefix(payload, "{") {
		return toolUseEnvelope{}, false
	}

	var envelope toolUseEnvelope
	if err := json.Unmarshal([]byte(payload), &envelope); err != nil {
		return toolUseEnvelope{}, false
	}
	if envelope.Type != toolUseResponseType || envelope.Name == "" {
		return toolUseEnvelope{}, false
	}
	return envelope, true
}

func decodeToolUseEnvelopes(payload string) ([]toolUseEnvelope, bool) {
	payload = strings.TrimSpace(payload)
	if payload == "" {
		return nil, false
	}
	if envelope, ok := decodeToolUseEnvelope(payload); ok {
		return []toolUseEnvelope{envelope}, true
	}
	if !strings.HasPrefix(payload, "[") {
		return nil, false
	}
	var envelopes []toolUseEnvelope
	if err := json.Unmarshal([]byte(payload), &envelopes); err != nil {
		return nil, false
	}
	if len(envelopes) == 0 {
		return nil, false
	}
	for _, envelope := range envelopes {
		if envelope.Type != toolUseResponseType || envelope.Name == "" {
			return nil, false
		}
	}
	return envelopes, true
}

func extractMarkdownFenceBody(trimmed string) (string, bool) {
	rest := strings.TrimPrefix(trimmed, "```")
	newlineIndex := strings.IndexByte(rest, '\n')
	if newlineIndex == -1 {
		return "", false
	}

	bodyWithClose := rest[newlineIndex+1:]
	closeIndex := strings.LastIndex(bodyWithClose, "```")
	if closeIndex == -1 {
		return "", false
	}

	return bodyWithClose[:closeIndex], true
}

// extractFencedToolUsePayload 在整段文本中搜索 fenced code block，
// 并返回第一个看起来像 tool_use JSON 的 body。
func extractFencedToolUsePayload(trimmed string) (string, bool) {
	searchFrom := 0
	for {
		start := strings.Index(trimmed[searchFrom:], "```")
		if start == -1 {
			return "", false
		}
		start += searchFrom

		body, next, ok := extractFenceBodyAt(trimmed, start)
		if !ok {
			return "", false
		}
		body = strings.TrimSpace(body)
		if _, ok := decodeToolUseEnvelope(body); ok {
			return body, true
		}
		searchFrom = next
	}
}

func extractFenceBodyAt(content string, start int) (body string, next int, ok bool) {
	rest := content[start:]
	if !strings.HasPrefix(rest, "```") {
		return "", len(content), false
	}

	rest = strings.TrimPrefix(rest, "```")
	newlineIndex := strings.IndexByte(rest, '\n')
	if newlineIndex == -1 {
		return "", len(content), false
	}

	bodyWithClose := rest[newlineIndex+1:]
	closeIndex := strings.Index(bodyWithClose, "```")
	if closeIndex == -1 {
		return "", len(content), false
	}

	consumed := start + 3 + newlineIndex + 1 + closeIndex + 3
	return bodyWithClose[:closeIndex], consumed, true
}

// extractEmbeddedJSONObject 在整段文本中搜索平衡的 JSON 对象，
// 并返回第一个可解析为 tool_use 的对象。
func extractEmbeddedJSONObject(trimmed string) (string, bool) {
	for start := strings.IndexByte(trimmed, '{'); start != -1; {
		payload, next, ok := extractBalancedJSONObject(trimmed, start)
		if ok {
			if _, matched := decodeToolUseEnvelope(payload); matched {
				return payload, true
			}
		}

		if next >= len(trimmed) {
			break
		}
		relative := strings.IndexByte(trimmed[next:], '{')
		if relative == -1 {
			break
		}
		start = next + relative
	}
	return "", false
}

func extractEmbeddedToolUseEnvelopes(trimmed string) []toolUseEnvelope {
	var envelopes []toolUseEnvelope
	for start := strings.IndexByte(trimmed, '{'); start != -1; {
		payload, next, ok := extractBalancedJSONObject(trimmed, start)
		if ok {
			if envelope, matched := decodeToolUseEnvelope(payload); matched {
				envelopes = append(envelopes, envelope)
			}
		}

		if next >= len(trimmed) {
			break
		}
		relative := strings.IndexByte(trimmed[next:], '{')
		if relative == -1 {
			break
		}
		start = next + relative
	}
	return envelopes
}

func extractBalancedJSONObject(content string, start int) (string, int, bool) {
	if start < 0 || start >= len(content) || content[start] != '{' {
		return "", len(content), false
	}

	depth := 0
	inString := false
	escaped := false

	for i := start; i < len(content); i++ {
		ch := content[i]

		if inString {
			if escaped {
				escaped = false
				continue
			}
			if ch == '\\' {
				escaped = true
				continue
			}
			if ch == '"' {
				inString = false
			}
			continue
		}

		switch ch {
		case '"':
			inString = true
		case '{':
			depth++
		case '}':
			depth--
			if depth == 0 {
				return content[start : i+1], i + 1, true
			}
		}
	}

	return "", len(content), false
}

func extractInvokeToolUseEnvelope(content string) (toolUseEnvelope, bool) {
	lower := strings.ToLower(content)
	start := strings.Index(lower, "<invoke")
	if start == -1 {
		return toolUseEnvelope{}, false
	}

	tagEnd := strings.Index(content[start:], ">")
	if tagEnd == -1 {
		return toolUseEnvelope{}, false
	}
	tagEnd += start

	openTag := content[start : tagEnd+1]
	name := extractTagAttribute(openTag, "name")
	if name == "" {
		return toolUseEnvelope{}, false
	}

	bodyStart := tagEnd + 1
	closeRel := strings.Index(strings.ToLower(content[bodyStart:]), "</invoke>")
	if closeRel == -1 {
		return toolUseEnvelope{}, false
	}

	input := decodeInvokeInput(content[bodyStart : bodyStart+closeRel])
	return toolUseEnvelope{
		Type:  toolUseResponseType,
		Name:  name,
		Input: input,
	}, true
}

func decodeInvokeInput(body string) json.RawMessage {
	body = strings.TrimSpace(body)
	if strings.HasPrefix(body, "{") && json.Valid([]byte(body)) {
		return json.RawMessage(body)
	}

	params := make(map[string]any)
	searchFrom := 0
	for searchFrom < len(body) {
		openRel := strings.Index(body[searchFrom:], "<")
		if openRel == -1 {
			break
		}
		open := searchFrom + openRel
		if open+1 < len(body) && body[open+1] == '/' {
			searchFrom = open + 2
			continue
		}

		tagEndRel := strings.Index(body[open:], ">")
		if tagEndRel == -1 {
			break
		}
		tagEnd := open + tagEndRel
		openTag := body[open : tagEnd+1]
		paramName := extractTagAttribute(openTag, "name")
		tagName := extractTagName(openTag)
		if tagName == "" {
			searchFrom = tagEnd + 1
			continue
		}
		// 支持 <file_path>value</file_path> 风格（tag 名即参数名）
		if paramName == "" {
			paramName = tagName
		}

		closeTag := "</" + tagName + ">"
		valueStart := tagEnd + 1
		closeRel := strings.Index(body[valueStart:], closeTag)
		if closeRel == -1 {
			searchFrom = tagEnd + 1
			continue
		}
		valueEnd := valueStart + closeRel
		params[paramName] = decodeInvokeParamValue(openTag, body[valueStart:valueEnd])
		searchFrom = valueEnd + len(closeTag)
	}

	if len(params) == 0 {
		return json.RawMessage(`{}`)
	}
	raw, err := json.Marshal(params)
	if err != nil {
		return json.RawMessage(`{}`)
	}
	return raw
}

func decodeInvokeParamValue(openTag, body string) any {
	value := extractTagAttribute(openTag, "value")
	if value == "" {
		value = html.UnescapeString(strings.TrimSpace(body))
	}

	stringAttr := strings.ToLower(strings.TrimSpace(extractTagAttribute(openTag, "string")))
	if stringAttr != "false" {
		return value
	}

	if value == "" {
		return ""
	}
	var decoded any
	if err := json.Unmarshal([]byte(value), &decoded); err == nil {
		return decoded
	}
	if intValue, err := strconv.Atoi(value); err == nil {
		return intValue
	}
	if floatValue, err := strconv.ParseFloat(value, 64); err == nil {
		return floatValue
	}
	if boolValue, err := strconv.ParseBool(value); err == nil {
		return boolValue
	}
	return value
}

func extractTagName(tag string) string {
	tag = strings.TrimSpace(strings.TrimPrefix(tag, "<"))
	tag = strings.TrimSuffix(tag, ">")
	tag = strings.TrimSpace(tag)
	if tag == "" || strings.HasPrefix(tag, "/") {
		return ""
	}
	for i, r := range tag {
		if r == ' ' || r == '\t' || r == '\n' || r == '\r' || r == '/' {
			return tag[:i]
		}
	}
	return tag
}

func extractTagAttribute(tag, name string) string {
	for _, quote := range []byte{'"', '\''} {
		prefix := name + "=" + string(quote)
		start := strings.Index(tag, prefix)
		if start == -1 {
			continue
		}
		valueStart := start + len(prefix)
		valueEndRel := strings.IndexByte(tag[valueStart:], quote)
		if valueEndRel == -1 {
			return ""
		}
		return html.UnescapeString(tag[valueStart : valueStart+valueEndRel])
	}
	return ""
}

func (runner *Runner) finishWithoutDone(ctx context.Context, state turnState) (message.Message, error) {
	if state.wroteOutput {
		_ = runner.ui.OnDone()
	}
	if ctx.Err() != nil {
		return message.Message{}, ctx.Err()
	}

	return message.Message{}, fmt.Errorf("模型流在未发送完成事件时结束")
}

func (runner *Runner) failAfterPartialOutput(wroteOutput bool, err error) error {
	if wroteOutput {
		_ = runner.ui.OnDone()
	}
	return err
}

func (runner *Runner) runToolCalls(ctx context.Context, calls []message.ToolCall) (message.Message, error) {
	results := make([]message.ToolResult, 0, len(calls))
	for start := 0; start < len(calls); {
		if runner.isToolCallConcurrencySafe(calls[start]) {
			end := start + 1
			for end < len(calls) && runner.isToolCallConcurrencySafe(calls[end]) {
				end++
			}
			batchResults, err := runner.runToolCallBatch(ctx, calls[start:end])
			if err != nil {
				return message.Message{}, err
			}
			results = append(results, batchResults...)
			start = end
			continue
		}

		result, err := runner.runToolCall(ctx, calls[start])
		if err != nil {
			return message.Message{}, err
		}
		results = append(results, result)
		start++
	}
	return buildToolResultsMessage(results), nil
}

func (runner *Runner) runToolCallBatch(ctx context.Context, calls []message.ToolCall) ([]message.ToolResult, error) {
	for _, call := range calls {
		if err := runner.emitToolCall(call); err != nil {
			return nil, err
		}
	}

	results := make([]message.ToolResult, len(calls))
	var wg sync.WaitGroup
	for i := range calls {
		i := i
		wg.Add(1)
		go func() {
			defer wg.Done()
			results[i] = runner.executeToolCall(ctx, calls[i])
		}()
	}
	wg.Wait()

	for i, result := range results {
		if err := runner.emitToolResult(calls[i], result); err != nil {
			return nil, err
		}
	}
	return results, nil
}

func (runner *Runner) runToolCall(ctx context.Context, call message.ToolCall) (message.ToolResult, error) {
	if err := runner.emitToolCall(call); err != nil {
		return message.ToolResult{}, err
	}

	result := runner.executeToolCall(ctx, call)
	if err := runner.emitToolResult(call, result); err != nil {
		return message.ToolResult{}, err
	}

	return result, nil
}

func (runner *Runner) emitToolCall(call message.ToolCall) error {
	event := ui.ToolCallEvent{
		ID:    call.ID,
		Name:  call.Name,
		Input: append(json.RawMessage(nil), call.Input...),
	}
	// Write/Edit 工具执行前同步读旧文件，供 UI diff 展示使用。
	// 只有 UI 声明会消费 OldContent 时才读取，避免 sinkUI 等无显示 UI 浪费 I/O。
	if consumer, ok := runner.ui.(ui.OldContentConsumer); ok && consumer.ConsumesOldContent() {
		switch strings.ToLower(strings.TrimSpace(call.Name)) {
		case "write", "edit", "update":
			var input struct {
				FilePath string `json:"file_path"`
				Path     string `json:"path"`
			}
			if err := json.Unmarshal(call.Input, &input); err == nil {
				path := input.FilePath
				if path == "" {
					path = input.Path
				}
				if path != "" {
					if !filepath.IsAbs(path) && runner.workRoot != "" {
						path = filepath.Join(runner.workRoot, path)
					}
					if data, err := os.ReadFile(path); err == nil {
						event.OldContent = string(data)
					}
				}
			}
		}
	}
	runner.recordTraceEvent("tool_call", map[string]any{
		"tool_use_id": call.ID,
		"name":        call.Name,
		"input":       json.RawMessage(append([]byte(nil), call.Input...)),
	})
	return runner.ui.OnToolCall(event)
}

func (runner *Runner) emitToolResult(call message.ToolCall, result message.ToolResult) error {
	runner.recordTraceEvent("tool_result", map[string]any{
		"tool_use_id": result.ToolUseID,
		"name":        call.Name,
		"is_error":    result.IsError,
		"content":     result.Content,
	})
	return runner.ui.OnToolResult(ui.ToolResultEvent{
		ToolUseID: result.ToolUseID,
		Name:      call.Name,
		Content:   result.Content,
		IsError:   result.IsError,
	})
}

func (runner *Runner) isToolCallConcurrencySafe(call message.ToolCall) bool {
	return runner.registry != nil && runner.registry.IsConcurrencySafe(call.Name, call.Input)
}

func (runner *Runner) executeToolCall(ctx context.Context, call message.ToolCall) message.ToolResult {
	if runner.registry == nil {
		return message.ToolResult{ToolUseID: call.ID, Content: "tool registry is nil", IsError: true}
	}

	selectedTool, ok := runner.registry.Get(call.Name)
	if !ok {
		return message.ToolResult{ToolUseID: call.ID, Content: fmt.Sprintf("unknown tool: %s", call.Name), IsError: true}
	}

	output, err := selectedTool.Run(ctx, call.Input)
	if err != nil {
		return message.ToolResult{ToolUseID: call.ID, Content: err.Error(), IsError: true}
	}

	return message.ToolResult{ToolUseID: call.ID, Content: output}
}

// 本文件定义 Bubble Tea 应用模型的创建、初始化和事件更新逻辑。
package bubble

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"time"

	"codex-agent-go/internal/skill"
	"github.com/charmbracelet/bubbles/cursor"
	"github.com/charmbracelet/bubbles/key"
	"github.com/charmbracelet/bubbles/textarea"
	"github.com/charmbracelet/bubbles/viewport"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
)

// pipelinePollCmd 异步检测 .pipeline-workspace/ 并返回 pipelineStateUpdatedMsg。
func pipelinePollCmd(activeAfter time.Time) tea.Cmd {
	return func() tea.Msg {
		cwd, err := os.Getwd()
		if err != nil {
			return pipelineStateUpdatedMsg{}
		}
		workspaceDir := filepath.Join(cwd, ".pipeline-workspace")
		return pipelineStateUpdatedMsg{state: loadPipelineState(workspaceDir, activeAfter)}
	}
}

// newModel 创建完整的 TUI 状态模型，并初始化输入框、滚动区和系统消息。
func newModel(ctx context.Context, runner Runner, sessionID string, controller ModelConfigController, settingsController SettingsController, subagentController SubagentController, sessionStore SessionStore, anchor *terminalCursorAnchor) appModel {
	now := time.Now()
	input := textarea.New()
	input.Prompt = ""
	input.Placeholder = ">"
	input.ShowLineNumbers = false
	input.EndOfBufferCharacter = ' '
	input.CharLimit = 0
	input.MaxHeight = 0
	input.SetWidth(72)
	input.SetHeight(inputMinVisibleLines)
	input.KeyMap.InsertNewline = key.NewBinding(
		key.WithKeys("ctrl+j", "alt+enter", "shift+enter"),
		key.WithHelp("ctrl+j", "newline"),
	)
	input.Cursor.SetMode(cursor.CursorStatic)
	applyTextareaPlainBackground(&input)
	input.Focus()

	vp := viewport.New(80, 20)
	vp.MouseWheelDelta = 1
	skillRoot, _ := os.Getwd()
	model := appModel{
		ctx:                 ctx,
		runner:              runner,
		sessionID:           sessionID,
		modelConfig:         controller,
		settingsConfig:      settingsController,
		subagents:           subagentController,
		sessionStore:        sessionStore,
		commandRegistry:     NewCommandRegistry(),
		skillRegistry:       skill.NewRegistry(skill.DefaultRoots(skillRoot)),
		cursorAnchor:        anchor,
		input:               input,
		viewport:            vp,
		cursorFrameAt:       now,
		pipelineActiveAfter: now,
		activeAssistant:     -1,
		activeThinking:      -1,
		doneAssistant:       -1,
		toolInspectIndex:    -1,
		toolHoverIndex:      -1,
		historyIndex:        -1,
		transcript: []transcriptEntry{
			{
				kind:  entrySystem,
				title: "system",
				body:  "Interactive mode is running on Bubble Tea. Use /help for commands.",
			},
		},
	}
	if provider, ok := runner.(tokenTracerURLProvider); ok {
		if url := strings.TrimSpace(provider.TokenTracerURL()); url != "" {
			model.transcript = append(model.transcript, transcriptEntry{
				kind:  entrySystem,
				title: "token-tracer",
				body:  "Token Tracer dashboard: " + url + "\nUse /token-tracer to show this link again.",
			})
		}
	}
	model.applyCursorAnimation()
	model.refreshViewport()
	return model
}

// applyTextareaPlainBackground 移除 textarea 默认的当前行背景色，让输入文字保持透明背景。
func applyTextareaPlainBackground(input *textarea.Model) {
	plain := lipgloss.NewStyle()
	input.FocusedStyle.Base = plain
	input.FocusedStyle.CursorLine = plain
	input.FocusedStyle.Text = plain
	input.FocusedStyle.Placeholder = lipgloss.NewStyle().Foreground(colorManager.LipglossColor(colorMarkdownRule))
	input.BlurredStyle.Base = plain
	input.BlurredStyle.CursorLine = plain
	input.BlurredStyle.Text = plain
	input.BlurredStyle.Placeholder = lipgloss.NewStyle().Foreground(colorManager.LipglossColor(colorMarkdownRule))
}

// Init 返回 Bubble Tea 启动时需要执行的初始命令。
func (m appModel) Init() tea.Cmd {
	return tea.Batch(m.input.Focus(), cursorFrameTick())
}

// Update 是 Bubble Tea 的核心状态机，负责把输入事件、模型事件和工具事件规约为新状态。
func (m appModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	var cmds []tea.Cmd

	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.ready = true
		m.width = msg.Width
		m.height = msg.Height
		m.relayout()
		m.resizeStreamingBuffers()
		m.refreshViewport()
		return m, nil
	case cursorFrameMsg:
		m.cursorFrameAt = time.Time(msg)
		m.spinnerFrameIdx++
		m.applyCursorAnimation()
		m.updateContextMeterAnimation()
		m.refreshActivityTasks()
		m.refreshSubagentPreviewFromTasks()
		if m.transcriptRefreshPending {
			if m.viewport.AtBottom() {
				m.refreshViewport()
			} else {
				m.refreshViewportPreservingOffset()
			}
		}
		return m, tea.Batch(cursorFrameTick(), pipelinePollCmd(m.pipelineActiveAfter))
	case assistantDeltaMsg:
		m.isGenerating = true
		m.consumeAssistantStreamDelta(string(msg))
		return m, nil
	case thinkingDeltaMsg:
		m.isGenerating = true
		m.consumeThinkingStreamDelta(string(msg))
		return m, nil
	case toolCallMsg:
		m.finalizeThinkingStream()
		m.finalizeAssistantStream(transcriptRenderFormatted)
		m.isGenerating = false
		m.recordToolCallEntry(msg.ID, msg.Name, json.RawMessage(msg.Input), msg.OldContent)
		return m, nil
	case toolResultMsg:
		m.finalizeThinkingStream()
		m.finalizeAssistantStream(transcriptRenderFormatted)
		status := "ok"
		if msg.IsError {
			status = "error"
		}
		m.recordToolResultEntry(msg.ToolUseID, msg.Name, status, msg.Content, msg.IsError)
		return m, nil
	case systemEventMsg:
		title := strings.TrimSpace(msg.Title)
		if title == "" {
			title = "system"
		}
		m.addEntry(transcriptEntry{
			kind:  entrySystem,
			title: title,
			body:  strings.TrimSpace(msg.Body),
			color: msg.Color,
		})
		return m, nil
	case doneMsg:
		m.finalizeThinkingStream()
		m.doneAssistant = m.finalizeAssistantStream(transcriptRenderFormatted)
		m.isGenerating = false
		m.refreshViewport()
		return m, nil
	case turnFinishedMsg:
		m.finalizeThinkingStream()
		if msg.err != nil {
			m.finalizeAssistantStream(transcriptRenderPlain)
			m.setAssistantRenderMode(m.doneAssistant, transcriptRenderPlain)
		} else {
			m.finalizeAssistantStream(transcriptRenderFormatted)
		}
		m.doneAssistant = -1
		m.isGenerating = false
		m.queryGuard.FinishModel()
		m.turnStartedAt = time.Time{}
		m.syncRunningFlags()
		if msg.err != nil {
			m.pendingToolCites = nil
			m.addEntry(transcriptEntry{
				kind:  entryError,
				title: "error",
				body:  msg.err.Error(),
			})
		}
		cmds = append(cmds, m.input.Focus())
		if queuedCmd := m.startNextQueuedTurn(); queuedCmd != nil {
			cmds = append(cmds, queuedCmd)
		}
	case shellFinishedMsg:
		m.queryGuard.FinishTerminal()
		m.syncRunningFlags()
		kind := entryTool
		if msg.err != nil {
			kind = entryError
		}
		m.addEntry(transcriptEntry{
			kind:  kind,
			title: "terminal",
			body:  shellResultBody(msg),
		})
		cmds = append(cmds, m.input.Focus())
	case subagentFinishedMsg:
		m.queryGuard.FinishModel()
		m.turnStartedAt = time.Time{}
		m.syncRunningFlags()
		agentTitle := resultDisplayName(msg.result)
		agentColor := strings.TrimSpace(msg.result.AgentColor)
		if msg.err != nil {
			m.addEntry(transcriptEntry{
				kind:  entryError,
				title: agentTitle,
				color: agentColor,
				body:  msg.err.Error(),
			})
		} else {
			m.addEntry(transcriptEntry{
				kind:  entrySystem,
				title: agentTitle,
				color: agentColor,
				body:  renderSubagentResult(msg.result),
			})
		}
		cmds = append(cmds, m.input.Focus())
		if queuedCmd := m.startNextQueuedTurn(); queuedCmd != nil {
			cmds = append(cmds, queuedCmd)
		}
	case sessionsLoadedMsg:
		if m.sessionPicker != nil {
			if msg.err != nil {
				m.sessionPicker.err = msg.err.Error()
			} else {
				m.sessionPicker.sessions = msg.sessions
				m.sessionPicker.loading = false
			}
		}
		return m, nil
	case sessionRestoredMsg:
		m.resetStreamingBuffers()
		m.resetToolInspect()
		m.clearInputTokens()
		if msg.err != nil {
			title := "sessions"
			if msg.source == sessionRestoreSubagentEnter {
				title = "subagent"
				m.subagentPicker = nil
			} else {
				m.sessionPicker = nil
			}
			m.addEntry(transcriptEntry{kind: entryError, title: title, body: msg.err.Error()})
		} else {
			switch msg.source {
			case sessionRestoreSubagentEnter:
				m.applySubagentPreviewRestore(msg)
			default:
				m.applySessionPickerRestore(msg)
			}
		}
		cmds = append(cmds, m.input.Focus())
		return m, tea.Batch(cmds...)
	case fileCompletionLoadedMsg:
		// 丢弃与当前 searchDir 不匹配的过期结果
		if m.completion != nil && m.completion.kind == completionKindFile &&
			m.completion.searchDir == msg.searchDir {
			m.completion.allItems = msg.items
			m.completion.filteredItems = msg.filtered
			m.completion.loading = false
			// 用当前 prefix 再过滤一次（加载期间前缀可能已改变）
			if m.completion.prefix != "" {
				m.completion.filteredItems = filterByPrefix(m.completion.allItems, m.completion.prefix)
			}
			if m.completion.selectedIndex >= len(m.completion.filteredItems) {
				m.completion.selectedIndex = 0
			}
			// 候选项加载完成后补全框高度变化，必须重新计算布局
			m.relayout()
		}
		return m, nil
	case pipelineStateUpdatedMsg:
		m.pipelineState = msg.state
		return m, nil
	case tea.KeyMsg:
		var rawMouseFragment bool
		msg, rawMouseFragment = m.filterRawMouseEscapeKey(msg)
		if rawMouseFragment {
			return m, nil
		}
		if m.settingWizard != nil {
			return m.handleSettingWizardKey(msg)
		}
		if m.modelWizard != nil {
			return m.handleModelWizardKey(msg)
		}
		if m.sessionPicker != nil {
			return m.handleSessionPickerKey(msg)
		}
		if m.subagentPicker != nil {
			return m.handleSubagentPickerKey(msg)
		}
		if m.toolInspectActive {
			return m.handleToolInspectKey(msg)
		}
		if msg.String() == "ctrl+t" {
			return m.openToolInspect()
		}
		if msg.String() == "ctrl+g" {
			return m.openSubagentPicker()
		}
		// 补全激活时：只拦截导航键和确认键，其余按键正常透传给输入框
		if m.completion != nil {
			switch msg.String() {
			case "esc":
				m.clearCompletionAndRelayout()
				return m, nil
			case "up", "ctrl+p":
				m.completion.navigateUp()
				return m, nil
			case "down", "ctrl+n":
				m.completion.navigateDown()
				return m, nil
			case "tab":
				visible := m.completion.visibleItems()
				if !m.completion.loading && len(visible) > 0 {
					selected := visible[m.completion.selectedIndex]
					switch m.completion.kind {
					case completionKindFile:
						isDir := strings.HasSuffix(selected, "/")
						if isDir {
							// 目录：不加空格，候选框保持开启以继续浏览
							m = m.applyFileCompletion(selected, false)
							if syncCmd := m.syncAtCompletion(); syncCmd != nil {
								return m, syncCmd
							}
							return m, nil
						}
						// 文件：行为与 Enter 一致（加空格 + 关闭候选框）
						m = m.applyFileCompletion(selected, true)
					case completionKindSkill:
						m = m.applySkillCompletion(selected)
					default:
						m = m.applyCommandCompletion(selected)
					}
				}
				m.clearCompletionAndRelayout()
				return m, nil
			case "enter":
				visible := m.completion.visibleItems()
				if !m.completion.loading && len(visible) > 0 {
					selected := visible[m.completion.selectedIndex]
					switch m.completion.kind {
					case completionKindFile:
						// Enter：补全路径并追加空格，结束引用
						m = m.applyFileCompletion(selected, true)
					case completionKindSkill:
						m = m.applySkillCompletion(selected)
					default:
						m = m.applyCommandCompletion(selected)
					}
				}
				m.clearCompletionAndRelayout()
				return m, nil
			}
			// 其他键：不 return，继续走下面的 switch 和 textarea 更新
		}
		if m.transcriptKeyScrollActive {
			switch msg.String() {
			case "up":
				m.viewport.ScrollUp(1)
				return m, nil
			case "down":
				m.viewport.ScrollDown(1)
				if m.viewport.AtBottom() {
					m.transcriptKeyScrollActive = false
				}
				return m, nil
			case "esc":
				if m.subagentPreview != nil {
					m.restoreMainTranscriptFromSubagentPreview()
					return m, m.input.Focus()
				}
				m.transcriptKeyScrollActive = false
				return m, nil
			}
			if isTextEditingKey(msg) || msg.String() == "tab" || msg.String() == "ctrl+c" {
				m.transcriptKeyScrollActive = false
			}
		}
		switch msg.String() {
		case "esc":
			if m.subagentPreview != nil {
				m.restoreMainTranscriptFromSubagentPreview()
				return m, m.input.Focus()
			}
		case "ctrl+c":
			now := time.Now()
			if !m.lastCtrlCAt.IsZero() && now.Sub(m.lastCtrlCAt) < time.Second {
				// 1 秒内连按两次：退出
				m.queryGuard.Cancel()
				m.chatQueue.Clear()
				return m, tea.Quit
			}
			// 第一次按：清空输入框（不进入历史）、关闭补全框
			m.lastCtrlCAt = now
			m.input.SetValue("")
			m.input.CursorEnd()
			m.clearInputTokens()
			m.pending = nil
			m.inputPasteFoldActive = false
			m.clearCompletionAndRelayout()
			m.syncInputMode()
			m.relayout()
			return m, nil
		case "ctrl+o":
			m.showThinking = !m.showThinking
			m.refreshViewportPreservingOffset()
			return m, nil
		case "up":
			return m.handleInputVerticalNavigation(-1)
		case "down":
			return m.handleInputVerticalNavigation(1)
		case "tab":
			if m.isModelWorkRunning() {
				return m.handleQueueSubmit()
			}
		case "enter":
			return m.handleSubmit()
		}
	case tea.MouseMsg:
		m.rawMouseEscapePending = ""
		if isHorizontalMouseWheel(msg) {
			return m, nil
		}
		if next, handled, cmd := m.handleTranscriptMouse(msg); handled {
			if msg.Action != tea.MouseActionMotion || next.selecting {
				next.transcriptKeyScrollActive = true
			}
			return next, cmd
		}
		if isMouseWheel(msg) {
			if m.isTranscriptViewportMouse(msg) {
				var viewportCmd tea.Cmd
				m.viewport, viewportCmd = m.viewport.Update(msg)
				m.transcriptKeyScrollActive = true
				return m, viewportCmd
			}
			return m, nil
		}
	}

	var viewportCmd tea.Cmd
	m.viewport, viewportCmd = m.viewport.Update(msg)
	cmds = append(cmds, viewportCmd)

	if !m.isTerminalWorkRunning() {
		var inputCmd tea.Cmd
		beforeValue := m.input.Value()
		m.input.SetHeight(inputMaxVisibleLines)
		inputCmd = m.updateTokenAwareInput(msg)
		textChanged := beforeValue != m.input.Value()
		if isTextEditingKey(msg) || textChanged {
			m.resetHistoryNavigation()
		}
		m.syncInputPasteFoldState(msg, beforeValue, textChanged)
		m.syncInputMode()
		m.relayout()
		cmds = append(cmds, inputCmd)

		// 每次文本变化后同步补全状态
		if isTextEditingKey(msg) || textChanged {
			// / 命令补全：整个输入以 / 开头时触发
			m.syncCommandCompletion()
			// $ skill 补全：词边界 $ 触发（只要 / 补全未激活）
			m.syncSkillCompletion()
			// @ 文件补全：词边界 @ 触发（只要 / 补全未激活）
			if cmd := m.syncAtCompletion(); cmd != nil {
				cmds = append(cmds, cmd)
			}
			// 补全状态可能已改变（如删除 @ 后清空），需要重新计算 viewport 高度
			m.relayout()
		}
	}
	m.applyCursorAnimation()

	return m, tea.Batch(cmds...)
}

// 本文件定义 Bubble Tea TUI 对外暴露的 UI 适配器。
package bubble

import (
	"codex-agent-go/internal/message"
	"codex-agent-go/internal/model"
	"codex-agent-go/internal/session"
	"codex-agent-go/internal/settings"
	"codex-agent-go/internal/subagent"
	"codex-agent-go/internal/ui"
	"context"
	"errors"
	"fmt"
	tea "github.com/charmbracelet/bubbletea"
	"os"
	"sync"
)

// Runner 描述 TUI 提交一轮用户输入时需要调用的对话运行器。
type Runner interface {
	RunTurn(ctx context.Context, input string) (message.Message, error)
	ResetHistory()
	LoadHistory(ctx context.Context, sessionID string) ([]message.Message, error)
}

// SupplementSubmitter describes runners that can accept instructions while a
// model turn is already running.
type SupplementSubmitter interface {
	SubmitSupplement(input string) bool
}

// SupplementStatsProvider exposes pending supplement counts for status UI.
type SupplementStatsProvider interface {
	PendingSupplementCount() int
}

// SessionStore 描述 TUI 列举和管理会话所需的最小接口。
type SessionStore interface {
	ListSessions(ctx context.Context) ([]session.SessionSummary, error)
}

// ModelConfigController 描述运行时读取和应用模型配置的控制器。
type ModelConfigController interface {
	CurrentModelConfig() model.Config
	ApplyModelConfig(model.Config) error
}

// ModelConfigSaver 描述可将模型配置持久化到磁盘的控制器扩展。
type ModelConfigSaver interface {
	SaveModelConfig(model.Config) error
}

// SettingsController 描述运行时读取和保存 UI/agent 设置的控制器。
type SettingsController interface {
	CurrentSettings() settings.Config
	SaveSettings(settings.Config) error
}

// SubagentController 描述 TUI 手动启动和查看 subagent 所需的能力。
type SubagentController interface {
	Run(context.Context, subagent.Request) (subagent.Result, error)
	Launch(context.Context, subagent.Request) (subagent.TaskSnapshot, error)
	ListTasks() []subagent.TaskSnapshot
}

// UI 是基于 Bubble Tea 的交互式终端界面实现。
type UI struct {
	mu                    sync.Mutex
	program               *tea.Program
	modelConfigController ModelConfigController
	settingsController    SettingsController
	subagentController    SubagentController
	sessionStore          SessionStore
}

// 确保 UI 满足通用终端 UI 接口。
var _ ui.UI = (*UI)(nil)

// New 创建一个尚未启动的 Bubble Tea UI 实例。
func New() *UI {
	return &UI{}
}

// SetModelConfigController 注入模型配置控制器，供 /model 向导读取和保存配置。
func (u *UI) SetModelConfigController(controller ModelConfigController) {
	u.mu.Lock()
	defer u.mu.Unlock()
	u.modelConfigController = controller
}

// SetSettingsController 注入 settings 控制器，供 /setting 和状态栏读取。
func (u *UI) SetSettingsController(controller SettingsController) {
	u.mu.Lock()
	defer u.mu.Unlock()
	u.settingsController = controller
}

// SetSubagentController 注入 subagent 控制器，供 /subagent 和 /tasks 使用。
func (u *UI) SetSubagentController(controller SubagentController) {
	u.mu.Lock()
	defer u.mu.Unlock()
	u.subagentController = controller
}

// SetSessionStore 注入 session store，供 /sessions 命令列举历史会话。
func (u *UI) SetSessionStore(store SessionStore) {
	u.mu.Lock()
	defer u.mu.Unlock()
	u.sessionStore = store
}

// Run 启动 Bubble Tea 主循环，并把输出写入带光标锚点修正的终端流。
func (u *UI) Run(ctx context.Context, runner Runner, sessionID string) error {
	u.mu.Lock()
	controller := u.modelConfigController
	settingsController := u.settingsController
	subagentController := u.subagentController
	sessionStore := u.sessionStore
	u.mu.Unlock()

	anchor := newTerminalCursorAnchor()
	appModel := newModel(ctx, runner, sessionID, controller, settingsController, subagentController, sessionStore, anchor)
	program := tea.NewProgram(
		appModel,
		tea.WithContext(ctx),
		tea.WithOutput(newAnchoredOutput(os.Stdout, anchor)),
		tea.WithAltScreen(),
		tea.WithMouseCellMotion(),
	)

	u.mu.Lock()
	u.program = program
	u.mu.Unlock()

	_, err := program.Run()

	u.mu.Lock()
	if u.program == program {
		u.program = nil
	}
	u.mu.Unlock()

	if errors.Is(err, tea.ErrInterrupted) {
		return nil
	}
	return err
}

// OnAssistantDelta 接收模型流式文本增量，并转发给 Bubble Tea 状态机。
func (u *UI) OnAssistantDelta(text string) error {
	if text == "" {
		return nil
	}
	return u.send(assistantDeltaMsg(text))
}

// OnThinkingDelta 接收模型 thinking 流，并转发给 Bubble Tea 状态机。
func (u *UI) OnThinkingDelta(text string) error {
	if text == "" {
		return nil
	}
	return u.send(thinkingDeltaMsg(text))
}

// OnToolCall 接收工具调用事件，并转发给 Bubble Tea 状态机展示。
func (u *UI) OnToolCall(event ui.ToolCallEvent) error {
	return u.send(toolCallMsg(event))
}

// OnToolResult 接收工具结果事件，并转发给 Bubble Tea 状态机展示。
func (u *UI) OnToolResult(event ui.ToolResultEvent) error {
	return u.send(toolResultMsg(event))
}

// OnDone 通知 TUI 当前 assistant 响应已经结束。
func (u *UI) OnDone() error {
	return u.send(doneMsg{})
}

// ConsumesOldContent 声明 bubble UI 会消费 OldContent 用于 diff 展示。
func (u *UI) ConsumesOldContent() bool { return true }

// OnSystemMessage 接收后台任务等系统事件，并转发给 Bubble Tea 状态机展示。
func (u *UI) OnSystemMessage(event ui.SystemEvent) error {
	return u.send(systemEventMsg(event))
}

// send 将外部事件安全地投递到正在运行的 Bubble Tea program。
func (u *UI) send(msg tea.Msg) error {
	u.mu.Lock()
	program := u.program
	u.mu.Unlock()
	if program == nil {
		return fmt.Errorf("bubble UI program is not running")
	}
	program.Send(msg)
	return nil
}

package tool

import (
	"context"
	"encoding/json"
)

type Tool interface {
	Name() string
	Description() string
	Run(ctx context.Context, input json.RawMessage) (string, error)
	InputSchema() json.RawMessage
}

type ConcurrencySafeTool interface {
	IsConcurrencySafe(input json.RawMessage) bool
}

package message

import "encoding/json"

type Role string

const (
	RoleSystem    Role = "system"
	RoleUser      Role = "user"
	RoleAssistant Role = "assistant"
)

type Message struct {
	Role        Role         `json:"role"`
	Content     string       `json:"content,omitempty"`
	ToolUse     *ToolCall    `json:"tool_use,omitempty"`
	ToolUses    []ToolCall   `json:"tool_uses,omitempty"`
	ToolResult  *ToolResult  `json:"tool_result,omitempty"`
	ToolResults []ToolResult `json:"tool_results,omitempty"`
}

type ToolCall struct {
	ID    string          `json:"id"`
	Name  string          `json:"name"`
	Input json.RawMessage `json:"input"`
}

type ToolResult struct {
	ToolUseID string `json:"tool_use_id"`
	Content   string `json:"content"`
	IsError   bool   `json:"is_error"`
}

package tool

import (
	"sort"
	"strings"

	"codex-agent-go/internal/model"
)

type Registry struct {
	tools map[string]Tool
}

func NewRegistry() *Registry {
	return &Registry{
		tools: make(map[string]Tool),
	}
}

func (r *Registry) Register(tool Tool) {
	if r == nil || tool == nil {
		return
	}
	if r.tools == nil {
		r.tools = make(map[string]Tool)
	}
	r.tools[tool.Name()] = tool
}

func (r *Registry) Get(name string) (Tool, bool) {
	if r == nil {
		return nil, false
	}
	tool, ok := r.tools[name]
	return tool, ok
}

func (r *Registry) IsConcurrencySafe(name string, input []byte) bool {
	registered, ok := r.Get(name)
	if !ok {
		return false
	}
	safeTool, ok := registered.(ConcurrencySafeTool)
	if !ok {
		return false
	}
	return safeTool.IsConcurrencySafe(append([]byte(nil), input...))
}

func (r *Registry) Describe() []string {
	if r == nil || len(r.tools) == 0 {
		return nil
	}

	names := make([]string, 0, len(r.tools))
	for name := range r.tools {
		names = append(names, name)
	}
	sort.Strings(names)

	descriptions := make([]string, 0, len(r.tools))
	for _, name := range names {
		tool := r.tools[name]
		description := tool.Name() + ": " + tool.Description()
		schema := strings.TrimSpace(string(tool.InputSchema()))
		if schema != "" {
			description += " input_schema=" + schema
		}
		descriptions = append(descriptions, description)
	}
	return descriptions
}

func (r *Registry) DescribeBrief() []string {
	if r == nil || len(r.tools) == 0 {
		return nil
	}

	names := make([]string, 0, len(r.tools))
	for name := range r.tools {
		names = append(names, name)
	}
	sort.Strings(names)

	descriptions := make([]string, 0, len(r.tools))
	for _, name := range names {
		tool := r.tools[name]
		description := strings.TrimSpace(tool.Description())
		if description == "" {
			descriptions = append(descriptions, tool.Name())
			continue
		}
		descriptions = append(descriptions, tool.Name()+": "+description)
	}
	return descriptions
}

// Definitions 返回注册表中所有工具的 ToolDefinition 切片，用于原生工具调用请求。
func (r *Registry) Definitions() []model.ToolDefinition {
	if r == nil || len(r.tools) == 0 {
		return nil
	}
	names := make([]string, 0, len(r.tools))
	for name := range r.tools {
		names = append(names, name)
	}
	sort.Strings(names)

	defs := make([]model.ToolDefinition, 0, len(names))
	for _, name := range names {
		t := r.tools[name]
		schema := t.InputSchema()
		if len(schema) == 0 {
			schema = []byte(`{"type":"object","properties":{}}`)
		}
		defs = append(defs, model.ToolDefinition{
			Name:        t.Name(),
			Description: t.Description(),
			InputSchema: schema,
		})
	}
	return defs
}

package model

import (
	"bufio"
	"bytes"
	"codex-agent-go/internal/message"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"sort"
	"strings"
)

// StreamEvent 表示一次流式输出事件。
// 一个事件只表达一种状态：
// 1) Delta 非空：收到一段增量文本
// 2) Done=true：流结束
// 3) Err 非空：流中出现错误
type StreamEvent struct {
	Delta     string
	Thinking  string
	ToolCalls []message.ToolCall
	Done      bool
	Err       error
	Usage     *Usage
}

// chatCompletionsStreamResponse 只建模流式响应里当前需要的字段。
// 不需要的字段故意省略，避免上层依赖供应商完整响应结构。
type chatCompletionsStreamResponse struct {
	Choices []struct {
		Delta struct {
			Content   string          `json:"content"`
			ToolCalls []toolCallDelta `json:"tool_calls,omitempty"`
		} `json:"delta"`
		FinishReason *string `json:"finish_reason"`
	} `json:"choices"`
	Usage *Usage `json:"usage,omitempty"`
	Error *struct {
		Message string `json:"message"`
		Type    string `json:"type"`
	} `json:"error,omitempty"`
}

// toolCallDelta 是 OpenAI 兼容接口流式 tool_calls 的单个增量。
type toolCallDelta struct {
	Index    int    `json:"index"`
	ID       string `json:"id"`
	Type     string `json:"type"`
	Function struct {
		Name      string `json:"name"`
		Arguments string `json:"arguments"`
	} `json:"function"`
}

// StreamMessage 以 SSE 方式返回模型增量输出。
// 调用方拿到 channel 后持续 range：
// - 处理 Delta
// - 处理 Err
// - 收到 Done 后结束当前轮次
func (c *Client) StreamMessage(ctx context.Context, messages []message.Message, tools []ToolDefinition) (<-chan StreamEvent, error) {
	// 模型接口要求至少有一条输入消息。
	if len(messages) == 0 {
		return nil, fmt.Errorf("messages 不能为空")
	}

	cfg := c.CurrentModelConfig()
	if shouldAttemptAnthropicStream(cfg) {
		events, err := c.streamAnthropicMessage(ctx, cfg, messages, tools)
		if err == nil {
			return events, nil
		}
	}

	return c.streamOpenAIMessage(ctx, cfg, messages, tools)
}

func (c *Client) streamOpenAIMessage(ctx context.Context, cfg Config, messages []message.Message, tools []ToolDefinition) (<-chan StreamEvent, error) {
	// 启用 stream=true，让服务端按 SSE 增量返回。
	reqBody := ChatCompletionsRequest{
		Model:         cfg.Model,
		Messages:      messages,
		Stream:        true,
		StreamOptions: &StreamOptions{IncludeUsage: true},
	}
	for _, t := range tools {
		reqBody.Tools = append(reqBody.Tools, openAITool{
			Type: "function",
			Function: openAIToolFunction{
				Name:        t.Name,
				Description: t.Description,
				Parameters:  t.InputSchema,
			},
		})
	}

	// 组装 JSON 请求体。
	bodyBytes, err := json.Marshal(reqBody)
	if err != nil {
		return nil, fmt.Errorf("序列化请求体失败: %w", err)
	}

	// 将上层 context 透传到底层 HTTP 请求，支持超时/取消。
	req, err := http.NewRequestWithContext(
		ctx,
		http.MethodPost,
		cfg.APIBaseURL+cfg.APIPath,
		bytes.NewReader(bodyBytes),
	)
	if err != nil {
		return nil, fmt.Errorf("创建 HTTP 请求失败: %w", err)
	}

	// 当前本地网关沿用标准 JSON 请求体和 Bearer 鉴权头。
	c.setRequestHeaders(req)

	// 发起请求；如果失败直接返回同步错误。
	resp, err := c.streamHTTPClient().Do(req)
	if err != nil {
		return nil, fmt.Errorf("调用模型接口失败: %w", err)
	}

	// SSE 流建立失败（非 2xx）时，读取错误体后返回。
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		respBytes, readErr := io.ReadAll(resp.Body)
		_ = resp.Body.Close()
		if readErr != nil {
			return nil, fmt.Errorf("模型接口返回异常状态 %d，且读取错误响应失败: %w", resp.StatusCode, readErr)
		}
		return nil, fmt.Errorf("模型接口返回异常状态 %d: %s", resp.StatusCode, strings.TrimSpace(string(respBytes)))
	}

	// 这里开始转入异步消费：
	// - 调用方立即拿到 channel，不阻塞当前 goroutine
	// - 后台 goroutine 负责解析 SSE 并投递事件
	events := make(chan StreamEvent)
	go c.consumeStream(ctx, resp, events)
	return events, nil
}

func shouldAttemptAnthropicStream(cfg Config) bool {
	baseURL := strings.ToLower(strings.TrimSpace(cfg.APIBaseURL))
	apiPath := strings.ToLower(strings.TrimSpace(cfg.APIPath))
	return normalizeProvider(cfg.Provider) == ProviderDeepSeek ||
		strings.Contains(baseURL, "/anthropic") ||
		strings.HasSuffix(apiPath, "/messages")
}

const (
	streamScannerInitialBufferBytes = 64 * 1024
	streamScannerMaxTokenBytes      = 32 * 1024 * 1024
)

func newStreamScanner(body io.Reader) *bufio.Scanner {
	scanner := bufio.NewScanner(body)
	scanner.Buffer(make([]byte, 0, streamScannerInitialBufferBytes), streamScannerMaxTokenBytes)
	return scanner
}

func (c *Client) handleStreamLine(ctx context.Context, line string, events chan<- StreamEvent) (done bool, err error) {
	line = strings.TrimSpace(line)
	if line == "" {
		return false, nil
	}
	if !strings.HasPrefix(line, "data:") {
		return false, nil
	}

	payload := strings.TrimSpace(strings.TrimPrefix(line, "data:"))
	return c.handleStreamPayload(ctx, payload, events)
}

func (c *Client) handleStreamPayload(ctx context.Context, payload string, events chan<- StreamEvent) (done bool, err error) {
	if payload == "" {
		return false, nil
	}
	if payload == "[DONE]" {
		_ = emitStreamEvent(ctx, events, StreamEvent{Done: true})
		return true, nil
	}

	chunk, err := decodeStreamChunk(payload)
	if err != nil {
		return false, fmt.Errorf("解析流式数据失败: %w", err)
	}
	if chunk.Error != nil {
		return false, fmt.Errorf("模型接口返回错误: %s", chunk.Error.Message)
	}

	return emitChunkEvents(ctx, chunk, events), nil
}

func decodeStreamChunk(payload string) (chatCompletionsStreamResponse, error) {
	var chunk chatCompletionsStreamResponse
	err := json.Unmarshal([]byte(payload), &chunk)
	return chunk, err
}

func emitChunkEvents(ctx context.Context, chunk chatCompletionsStreamResponse, events chan<- StreamEvent) (done bool) {
	if chunk.Usage != nil {
		if !emitStreamEvent(ctx, events, StreamEvent{Usage: chunk.Usage}) {
			return true
		}
	}
	if len(chunk.Choices) == 0 {
		return false
	}

	delta := chunk.Choices[0].Delta.Content
	if delta != "" {
		if !emitStreamEvent(ctx, events, StreamEvent{Delta: delta}) {
			return true
		}
	}

	finishReason := chunk.Choices[0].FinishReason
	if finishReason != nil && *finishReason != "" {
		_ = emitStreamEvent(ctx, events, StreamEvent{Done: true})
		return true
	}

	return false
}

// activeOpenAIToolCall 追踪正在流式累积的 OpenAI tool_call 增量。
type activeOpenAIToolCall struct {
	id   string
	name string
	args strings.Builder
}

func openAIToolCallsFromAccumulated(accumulated map[int]*activeOpenAIToolCall) []message.ToolCall {
	calls := make([]message.ToolCall, 0, len(accumulated))
	indexes := make([]int, 0, len(accumulated))
	for index := range accumulated {
		indexes = append(indexes, index)
	}
	sort.Ints(indexes)
	for _, index := range indexes {
		call := accumulated[index]
		if call == nil || call.name == "" {
			continue
		}
		args := call.args.String()
		input := json.RawMessage(`{}`)
		if len(args) > 0 && json.Valid([]byte(args)) {
			input = json.RawMessage(args)
		}
		calls = append(calls, message.ToolCall{
			ID:    call.id,
			Name:  call.name,
			Input: input,
		})
	}
	return calls
}

// consumeStream 负责把 SSE 文本行转换为 StreamEvent，并累积原生 tool_calls。
func (c *Client) consumeStream(ctx context.Context, resp *http.Response, events chan<- StreamEvent) {
	defer close(events)
	defer func(Body io.ReadCloser) {
		_ = Body.Close()
	}(resp.Body)

	scanner := newStreamScanner(resp.Body)
	// 按 index 累积 tool_calls，支持单次响应中多个工具调用
	accumulated := map[int]*activeOpenAIToolCall{}

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || !strings.HasPrefix(line, "data:") {
			continue
		}
		payload := strings.TrimSpace(strings.TrimPrefix(line, "data:"))
		if payload == "" || payload == "[DONE]" {
			break
		}

		chunk, err := decodeStreamChunk(payload)
		if err != nil {
			_ = emitStreamEvent(ctx, events, StreamEvent{Err: fmt.Errorf("解析流式数据失败: %w", err)})
			return
		}
		if chunk.Error != nil {
			_ = emitStreamEvent(ctx, events, StreamEvent{Err: fmt.Errorf("模型接口返回错误: %s", chunk.Error.Message)})
			return
		}

		// 累积 delta.tool_calls
		if len(chunk.Choices) > 0 {
			for _, tc := range chunk.Choices[0].Delta.ToolCalls {
				call, ok := accumulated[tc.Index]
				if !ok {
					call = &activeOpenAIToolCall{}
					accumulated[tc.Index] = call
				}
				if tc.ID != "" {
					call.id = tc.ID
				}
				if tc.Function.Name != "" {
					call.name = tc.Function.Name
				}
				call.args.WriteString(tc.Function.Arguments)
			}
		}

		// Usage
		if chunk.Usage != nil {
			if !emitStreamEvent(ctx, events, StreamEvent{Usage: chunk.Usage}) {
				return
			}
		}

		if len(chunk.Choices) == 0 {
			continue
		}

		// 文本内容 delta
		if delta := chunk.Choices[0].Delta.Content; delta != "" {
			if !emitStreamEvent(ctx, events, StreamEvent{Delta: delta}) {
				return
			}
		}

		// finish_reason：先 flush 工具调用，再发 Done
		finishReason := chunk.Choices[0].FinishReason
		if finishReason != nil && *finishReason != "" {
			if calls := openAIToolCallsFromAccumulated(accumulated); len(calls) > 0 {
				if !emitStreamEvent(ctx, events, StreamEvent{ToolCalls: calls}) {
					return
				}
			}
			_ = emitStreamEvent(ctx, events, StreamEvent{Done: true})
			return
		}
	}

	if err := scanner.Err(); err != nil {
		_ = emitStreamEvent(ctx, events, StreamEvent{Err: fmt.Errorf("读取流式响应失败: %w", err)})
		return
	}

	// EOF 前未收到 finish_reason：flush 积累的工具调用后发 Done
	if calls := openAIToolCallsFromAccumulated(accumulated); len(calls) > 0 {
		if !emitStreamEvent(ctx, events, StreamEvent{ToolCalls: calls}) {
			return
		}
	}
	_ = emitStreamEvent(ctx, events, StreamEvent{Done: true})
}

// emitStreamEvent 在 ctx 取消时主动放弃发送，避免 goroutine 卡在 channel send 上，
// 从而保证 resp.Body 的 defer Close 可以执行。
func emitStreamEvent(ctx context.Context, events chan<- StreamEvent, ev StreamEvent) bool {
	select {
	case events <- ev:
		return true
	case <-ctx.Done():
		return false
	}
}

package session

import (
	"bufio"
	"context"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"codex-agent-go/internal/message"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

const defaultSessionsDir = "sessions"

type Record struct {
	Seq       int64           `json:"seq"`
	Message   message.Message `json:"message"`
	CreatedAt time.Time       `json:"created_at"`
}

type JSONLStore struct {
	baseDir string
	nowFn   func() time.Time
}

var _ Store = (*JSONLStore)(nil)

// NewJSONLStore 在指定目录下创建存储。
// baseDir 是存放所有会话数据的根目录，通常传项目 cwd。
func NewJSONLStore(baseDir string) (*JSONLStore, error) {
	if strings.TrimSpace(baseDir) == "" {
		return nil, fmt.Errorf("baseDir 不能为空")
	}
	return &JSONLStore{baseDir: baseDir, nowFn: time.Now}, nil
}

// NewJSONLStoreInCwd 以当前工作目录作为 baseDir 创建存储，
// 会话数据存放在 .ccagent/ 子目录下。
// 调用方不需要感知路径细节。
func NewJSONLStoreInCwd() (*JSONLStore, error) {
	cwd, err := os.Getwd()
	if err != nil {
		return nil, fmt.Errorf("获取当前目录失败: %w", err)
	}
	baseDir := filepath.Join(cwd, ".ccagent")
	return NewJSONLStore(baseDir)
}

func (s *JSONLStore) CreateRoot(ctx context.Context, request CreateRootRequest) (Meta, error) {
	if err := ctx.Err(); err != nil {
		return Meta{}, err
	}

	sessionID := request.SessionID

	exists, err := s.Exists(ctx, sessionID)
	if err != nil {
		return Meta{}, err
	}
	if exists {
		return Meta{}, fmt.Errorf("session 已存在: %s", sessionID)
	}

	meta := Meta{
		SessionID: sessionID,
		CreatedAt: s.nowFn().UTC(),
	}
	if err := s.writeMeta(ctx, meta); err != nil {
		return Meta{}, err
	}
	return meta, nil
}

func (s *JSONLStore) Fork(ctx context.Context, request ForkRequest) (Meta, error) {
	if err := ctx.Err(); err != nil {
		return Meta{}, err
	}

	parentID := strings.TrimSpace(request.ParentSessionID)
	if parentID == "" {
		return Meta{}, fmt.Errorf("ParentSessionID 不能为空")
	}
	if _, err := s.GetMeta(ctx, parentID); err != nil {
		return Meta{}, fmt.Errorf("读取父会话元数据失败: %w", err)
	}

	parentHistory, err := s.LoadResolvedHistory(ctx, parentID)
	if err != nil {
		return Meta{}, fmt.Errorf("读取父会话历史失败: %w", err)
	}

	forkFromSeq := request.ForkFromSeq
	switch {
	case forkFromSeq == -1:
		forkFromSeq = int64(len(parentHistory))
	case forkFromSeq < -1:
		return Meta{}, fmt.Errorf("ForkFromSeq 不能小于 -1: %d", forkFromSeq)
	}
	if forkFromSeq > int64(len(parentHistory)) {
		return Meta{}, fmt.Errorf("ForkFromSeq 超出父会话长度: %d > %d", forkFromSeq, len(parentHistory))
	}

	sessionID := request.SessionID

	exists, err := s.Exists(ctx, sessionID)
	if err != nil {
		return Meta{}, err
	}
	if exists {
		return Meta{}, fmt.Errorf("session 已存在: %s", sessionID)
	}

	meta := Meta{
		SessionID:       sessionID,
		ParentSessionID: parentID,
		ForkFromSeq:     forkFromSeq,
		CreatedAt:       s.nowFn().UTC(),
	}
	if err := s.writeMeta(ctx, meta); err != nil {
		return Meta{}, err
	}
	return meta, nil
}

func (s *JSONLStore) GetMeta(ctx context.Context, sessionID string) (Meta, error) {
	if err := ctx.Err(); err != nil {
		return Meta{}, err
	}
	if strings.TrimSpace(sessionID) == "" {
		return Meta{}, fmt.Errorf("sessionID 不能为空")
	}

	data, err := os.ReadFile(s.metaPath(sessionID))
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return Meta{}, fmt.Errorf("session 不存在: %s", sessionID)
		}
		return Meta{}, err
	}

	var meta Meta
	if err := json.Unmarshal(data, &meta); err != nil {
		return Meta{}, fmt.Errorf("解析 meta.json 失败: %w", err)
	}
	if meta.SessionID == "" {
		meta.SessionID = sessionID
	}
	return meta, nil
}

func (s *JSONLStore) Exists(ctx context.Context, sessionID string) (bool, error) {
	if err := ctx.Err(); err != nil {
		return false, err
	}
	if strings.TrimSpace(sessionID) == "" {
		return false, fmt.Errorf("sessionID 不能为空")
	}

	_, err := os.Stat(s.metaPath(sessionID))
	if err == nil {
		return true, nil
	}
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	return false, err
}

func (s *JSONLStore) Append(ctx context.Context, sessionID string, msgs ...message.Message) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if len(msgs) == 0 {
		return nil
	}
	if strings.TrimSpace(sessionID) == "" {
		return fmt.Errorf("sessionID 不能为空")
	}
	exists, err := s.Exists(ctx, sessionID)
	if err != nil {
		return err
	}
	if !exists {
		if _, err := s.CreateRoot(ctx, CreateRootRequest{SessionID: sessionID}); err != nil {
			return err
		}
	} else if _, err := s.GetMeta(ctx, sessionID); err != nil {
		return err
	}

	records, err := s.readOwnRecords(ctx, sessionID)
	if err != nil {
		return err
	}

	nextSeq := int64(0)
	if len(records) > 0 {
		nextSeq = records[len(records)-1].Seq + 1
	}

	if err := os.MkdirAll(s.sessionDir(sessionID), 0o755); err != nil {
		return err
	}
	f, err := os.OpenFile(s.transcriptPath(sessionID), os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
	if err != nil {
		return err
	}
	defer func() { _ = f.Close() }()

	enc := json.NewEncoder(f)
	now := s.nowFn().UTC()
	for i := range msgs {
		if err := ctx.Err(); err != nil {
			return err
		}
		rec := Record{Seq: nextSeq, Message: msgs[i], CreatedAt: now}
		if err := enc.Encode(rec); err != nil {
			return err
		}
		nextSeq++
	}
	return nil
}

func (s *JSONLStore) LoadResolvedHistory(ctx context.Context, sessionID string) ([]message.Message, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	meta, err := s.GetMeta(ctx, sessionID)
	if err != nil {
		return nil, err
	}

	ownRecords, err := s.readOwnRecords(ctx, sessionID)
	if err != nil {
		return nil, err
	}
	ownHistory := make([]message.Message, 0, len(ownRecords))
	for i := range ownRecords {
		ownHistory = append(ownHistory, ownRecords[i].Message)
	}

	if meta.ParentSessionID == "" {
		return ownHistory, nil
	}

	parentHistory, err := s.LoadResolvedHistory(ctx, meta.ParentSessionID)
	if err != nil {
		return nil, err
	}
	if meta.ForkFromSeq < 0 {
		return nil, fmt.Errorf("非法 fork_from_seq: %d", meta.ForkFromSeq)
	}
	if meta.ForkFromSeq > int64(len(parentHistory)) {
		return nil, fmt.Errorf("fork_from_seq 超过父会话长度: %d > %d", meta.ForkFromSeq, len(parentHistory))
	}

	resolved := make([]message.Message, 0, int(meta.ForkFromSeq)+len(ownHistory))
	resolved = append(resolved, parentHistory[:meta.ForkFromSeq]...)
	resolved = append(resolved, ownHistory...)
	return resolved, nil
}

func (s *JSONLStore) writeMeta(ctx context.Context, meta Meta) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if strings.TrimSpace(meta.SessionID) == "" {
		return fmt.Errorf("SessionID 不能为空")
	}
	if err := os.MkdirAll(s.sessionDir(meta.SessionID), 0o755); err != nil {
		return err
	}
	data, err := json.MarshalIndent(meta, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(s.metaPath(meta.SessionID), data, 0o644)
}

func (s *JSONLStore) readOwnRecords(ctx context.Context, sessionID string) ([]Record, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}

	path := s.transcriptPath(sessionID)
	f, err := os.Open(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, err
	}
	defer func() { _ = f.Close() }()

	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)

	records := make([]Record, 0, 64)
	for scanner.Scan() {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		var rec Record
		if err := json.Unmarshal([]byte(line), &rec); err != nil {
			return nil, fmt.Errorf("解析 transcript 失败(%s): %w", path, err)
		}
		records = append(records, rec)
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return records, nil
}

func (s *JSONLStore) sessionDir(sessionID string) string {
	return filepath.Join(s.baseDir, defaultSessionsDir, sessionID)
}

func (s *JSONLStore) metaPath(sessionID string) string {
	return filepath.Join(s.sessionDir(sessionID), "meta.json")
}

func (s *JSONLStore) transcriptPath(sessionID string) string {
	return filepath.Join(s.sessionDir(sessionID), "transcript.jsonl")
}

// TranscriptPath 返回指定 session 的 transcript 文件路径。
func (s *JSONLStore) TranscriptPath(sessionID string) string {
	return s.transcriptPath(sessionID)
}

// GenerateSessionID 生成一个随机的 session ID（16 字节 hex 字符串）。
func GenerateSessionID() (string, error) {
	buf := make([]byte, 16)
	if _, err := rand.Read(buf); err != nil {
		return "", err
	}
	return hex.EncodeToString(buf), nil
}

// OpenOrCreate 按 key（通常传 cwd）查找已有会话并返回其 sessionID；
// 若不存在则创建一个新会话。
// 这样调用方完全不需要关心 session ID 的生成和查找。
func (s *JSONLStore) OpenOrCreate(ctx context.Context, key string) (string, error) {
	if err := ctx.Err(); err != nil {
		return "", err
	}
	if strings.TrimSpace(key) == "" {
		return "", fmt.Errorf("key 不能为空")
	}

	// 用 key 的哈希作为索引文件名，避免 key 中包含路径分隔符等特殊字符。
	indexPath := s.keyIndexPath(key)

	// 如果索引文件存在，说明该 key 已经绑定了一个 session。
	existingID, err := os.ReadFile(indexPath)
	if err == nil {
		sessionID := strings.TrimSpace(string(existingID))
		// 再确认 session 目录本身也存在（防止文件被手动删除的情况）。
		exists, existsErr := s.Exists(ctx, sessionID)
		if existsErr != nil {
			return "", existsErr
		}
		if exists {
			return sessionID, nil
		}
		// session 目录不存在了，索引失效，重新创建。
	}
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return "", fmt.Errorf("读取 session 索引失败: %w", err)
	}

	// 生成新 session ID 并创建会话。
	sessionID, err := GenerateSessionID()
	if err != nil {
		return "", err
	}
	if _, err := s.CreateRoot(ctx, CreateRootRequest{SessionID: sessionID}); err != nil {
		return "", err
	}

	// 将 key -> sessionID 的映射写入索引文件。
	if err := os.MkdirAll(filepath.Dir(indexPath), 0o755); err != nil {
		return "", err
	}
	if err := os.WriteFile(indexPath, []byte(sessionID), 0o644); err != nil {
		return "", fmt.Errorf("写入 session 索引失败: %w", err)
	}

	return sessionID, nil
}

// keyIndexPath 用 key 的内容（去掉非法字符后）生成一个索引文件路径。
// 存放在 baseDir/index/ 目录下。
func (s *JSONLStore) keyIndexPath(key string) string {
	// 将路径分隔符和特殊字符替换为 _，让 key 可以安全作为文件名。
	safe := strings.NewReplacer("/", "_", "\\", "_", ":", "_", " ", "_").Replace(key)
	if len(safe) > 200 {
		safe = safe[len(safe)-200:]
	}
	return filepath.Join(s.baseDir, "index", safe)
}

// SessionSummary 是 ListSessions 返回的会话摘要信息。
type SessionSummary struct {
	SessionID      string
	CreatedAt      time.Time
	FirstMessage   string // 第一条用户消息的前 80 个字符，可能为空
	TranscriptSize int64  // transcript 文件大小（字节）
}

// ListSessions 枚举所有已存储的会话，按创建时间倒序返回。
// 读取失败的会话会被跳过。
func (s *JSONLStore) ListSessions(ctx context.Context) ([]SessionSummary, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}

	sessionsDir := filepath.Join(s.baseDir, defaultSessionsDir)
	entries, err := os.ReadDir(sessionsDir)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, err
	}

	var summaries []SessionSummary
	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		sessionID := entry.Name()
		meta, err := s.GetMeta(ctx, sessionID)
		if err != nil {
			continue // 跳过读取失败的会话
		}

		summary := SessionSummary{
			SessionID: meta.SessionID,
			CreatedAt: meta.CreatedAt,
		}

		// 尝试读取第一条用户消息和 transcript 文件大小
		if fi, err := os.Stat(s.transcriptPath(sessionID)); err == nil {
			summary.TranscriptSize = fi.Size()
		}
		records, err := s.readOwnRecords(ctx, sessionID)
		if err == nil {
			for _, rec := range records {
				if rec.Message.Role == "user" && rec.Message.Content != "" {
					msg := rec.Message.Content
					if len(msg) > 80 {
						msg = msg[:80]
					}
					summary.FirstMessage = msg
					break
				}
			}
		}

		summaries = append(summaries, summary)
	}

	// 按创建时间倒序排列（最新的在前）
	sort.Slice(summaries, func(i, j int) bool {
		return summaries[i].CreatedAt.After(summaries[j].CreatedAt)
	})

	return summaries, nil
}

// 本文件集中定义 Bubble Tea TUI 的状态类型、内部消息和模型切换向导数据结构。
package bubble

import (
	"codex-agent-go/internal/loop"
	"codex-agent-go/internal/model"
	"codex-agent-go/internal/settings"
	"codex-agent-go/internal/skill"
	"codex-agent-go/internal/subagent"
	"codex-agent-go/internal/ui"
	"context"
	"github.com/charmbracelet/bubbles/textarea"
	"github.com/charmbracelet/bubbles/viewport"
	"time"
)

// entryKind 表示 transcript 中一条消息的来源类别。
type entryKind int

type transcriptRenderMode uint8

const (
	transcriptRenderFormatted transcriptRenderMode = iota
	transcriptRenderStreamingPlain
	transcriptRenderPlain
)

// transcript 条目类型常量。
const (
	// entrySystem 表示系统状态或命令提示消息。
	entrySystem entryKind = iota
	// entryUser 表示用户输入消息。
	entryUser
	// entryAssistant 表示 assistant 的模型输出消息。
	entryAssistant
	// entryThinking 表示模型 thinking 过程消息。
	entryThinking
	// entryTool 表示工具调用、工具结果或终端命令消息。
	entryTool
	// entryError 表示错误消息。
	entryError
)

// transcriptEntry 是聊天历史区的一条可渲染记录。
type transcriptEntry struct {
	kind           entryKind
	title          string
	body           string
	inputTokens    []inputToken // visual-only metadata; body remains the raw submitted/session text
	color          string       // 可选：标题颜色（lipgloss 颜色字符串），与 subagents 面板保持一致
	isError        bool         // true for tool results with IsError=true
	toolUseID      string
	toolName       string
	toolStatus     string
	toolTarget     string
	toolResult     string
	toolExpanded   bool
	toolFocused    bool
	toolHovered    bool
	toolResultOnly bool
	citations      []toolCitation
	createdAt      time.Time
	version        int
	renderMode     transcriptRenderMode
}

type toolCitation struct {
	toolUseID string
	name      string
	target    string
	status    string
	preview   string
	isError   bool
}

// selectionPoint 表示 transcript 渲染结果中的一个显示单元格坐标。
type selectionPoint struct {
	row int
	col int
}

// assistantDeltaMsg 表示模型流式输出的一段文本增量。
type assistantDeltaMsg string

// thinkingDeltaMsg 表示模型 thinking 流式输出的一段文本增量。
type thinkingDeltaMsg string

// toolCallMsg 表示工具调用事件。
type toolCallMsg ui.ToolCallEvent

// toolResultMsg 表示工具结果事件。
type toolResultMsg ui.ToolResultEvent

// systemEventMsg 表示后台任务等系统事件。
type systemEventMsg ui.SystemEvent

// doneMsg 表示当前 assistant 输出已经结束。
type doneMsg struct{}

// turnFinishedMsg 表示一轮模型调用已经结束，并携带可能的错误。
type turnFinishedMsg struct{ err error }

// shellFinishedMsg 表示一次终端命令执行完成后的结果。
type shellFinishedMsg struct {
	command string
	stdout  string
	stderr  string
	err     error
}

type subagentFinishedMsg struct {
	result subagent.Result
	err    error
}

// cursorFrameMsg 驱动自定义光标动画更新一帧。
type cursorFrameMsg time.Time

// modelWizardStep 表示 /model 向导当前所处的步骤。
type modelWizardStep int

// /model 向导步骤常量。
const (
	// modelWizardProvider 表示正在选择 provider。
	modelWizardProvider modelWizardStep = iota
	// modelWizardConfirm 表示正在确认将要应用的模型配置。
	modelWizardConfirm
)

// modelProviderOption 描述 /model 向导中的一个 provider 选项。
type modelProviderOption struct {
	id          string
	label       string
	description string
}

// modelProviderOptions 是当前 TUI 支持切换的 provider 列表。
var modelProviderOptions = []modelProviderOption{
	{
		id:          model.ProviderCustom,
		label:       "custom",
		description: "Local or custom OpenAI-compatible endpoint",
	},
	{
		id:          model.ProviderDeepSeek,
		label:       "deepseek",
		description: "DeepSeek official OpenAI-compatible endpoint",
	},
}

// modelWizard 保存 /model 交互向导的临时 UI 状态。
type modelWizard struct {
	step          modelWizardStep
	selectedIndex int
	err           string
}

type settingWizardStep int

const (
	settingWizardContext settingWizardStep = iota
	settingWizardRunMode
	settingWizardLimit
	settingWizardConfirm
)

type settingOption struct {
	label       string
	description string
	apply       func(*settings.Config)
}

type settingWizard struct {
	step     settingWizardStep
	selected map[settingWizardStep]int
	draft    settings.Config
	err      string
}

// contextMeterAnimation 记录 context 进度条从旧 token 用量跳到新用量的短时动画。
type contextMeterAnimation struct {
	initialized bool
	startedAt   time.Time
	fromUsed    float64
	fromCache   float64
	targetUsed  int
	targetCache int
}

// newModelWizard 根据当前配置创建 provider 选择向导，并默认选中当前 provider。
func newModelWizard(current model.Config) *modelWizard {
	selected := 0
	for i, option := range modelProviderOptions {
		if option.id == current.Provider {
			selected = i
			break
		}
	}
	return &modelWizard{step: modelWizardProvider, selectedIndex: selected}
}

// selectedProvider 返回当前选中的 provider，并在索引越界时进行纠正。
func (w *modelWizard) selectedProvider() modelProviderOption {
	if w == nil || len(modelProviderOptions) == 0 {
		return modelProviderOption{}
	}
	if w.selectedIndex < 0 {
		w.selectedIndex = 0
	}
	if w.selectedIndex >= len(modelProviderOptions) {
		w.selectedIndex = len(modelProviderOptions) - 1
	}
	return modelProviderOptions[w.selectedIndex]
}

